function selectCard(i){if(S?.screen!=='battle'||!S.battle.hand[i])return;battleFX=null;AV.cue('select');S.battle.preview=S.battle.preview===i?null:i;render();}
function confirmCard(){const b=S?.battle;if(!b||!Number.isInteger(b.preview))return;const i=b.preview;b.preview=null;playCard(i);}
function renderCardDock(){const b=S.battle,i=b.preview,id=Number.isInteger(i)?b.hand[i]:null,c=id?cardDetail(id):null;return `<div class="card-dock"><div><strong>${c?esc(c.name):'カードを選択'}</strong><small>${c?esc(cardText(c))+((c.effect.aoe||c.effect.allPoison||c.effect.allWeak)?'【生存する敵全'+b.enemies.filter(e=>e.hp>0).length+'体が対象】':(c.effect.hit||c.effect.blockHit||c.effect.executeHit||c.effect.detonate||c.effect.poison||c.effect.weak||c.effect.bleed||c.effect.vuln?'【選択中の敵が対象】':'【自分が対象】')):'カード確認 → 対象を選択 → 使用'}</small>${c?synergyNote(c):''}</div><button class="btn" onclick="confirmCard()" ${!c||useRestriction(c,b)?'disabled':''}>${c?'使用 '+c.cost+'EN':'使用する'}</button><button class="btn dock-turn" onclick="endTurn()">ターン終了</button></div>`}
function heroArt(cls=S.cls){return {warrior:0,rogue:1,mage:2,occult:3}[cls]||0;}
function oldEnemyArt(e,type){if(type==='boss')return 5+Math.min(S.act,2);if(/魔|司祭|預言|亡霊/.test(e.name))return 6;if(/骨|衛兵|騎士|番人|墓守|亡者/.test(e.name))return 5;return 4;}
function characterArt(index,extra='',label=''){return `<span class="painted-character art-${index} ${extra}" role="img" aria-label="${esc(label)}"></span>`;}
function oldCardArt(c){const e=c.effect;if(e.heal||e.passiveHeal)return 4;if(c.type==='power'&&(e.str||e.thorns))return 3;if(e.block||e.passiveBlock)return 1;if(e.poison||e.allPoison||e.draw||e.energy||e.vuln||c.cls==='occult'||c.cls==='mage')return 5;if(e.aoe||e.hit>=15)return 2;return 0;}
function renderCard(id,index,mode='hand'){const c=cardDetail(id),affordable=mode==='hand'&&S.battle&&c.cost<=S.battle.energy,cl=mode==='hand'?(affordable?'playable'+(S.battle.preview===index?' card-selected':''):'unplayable'):'reward';return `<button class="card illustrated-card rarity-${c.rarity} ${c.type} ${cl}" ${mode==='hand'?`onclick="selectCard(${index})"`:(mode==='treasure'?`onclick="takeTreasure('card','${id}')"`:mode==='reward'?`onclick="previewReward('${id}')"`:'')} ${mode==='hand'&&!affordable?'disabled':''}><span class="cost">${c.cost}</span><span class="name">${esc(c.name)}${c.up?' +':''}</span><span class="card-paint card-paint-${cardArt(c)}" role="img" aria-label="${esc(c.name)}の挿絵"></span><span class="card-kind">${{attack:'アタック',skill:'スキル',power:'パワー',curse:'呪い'}[c.type]}</span><span class="desc">${esc(cardText(c))}</span><span class="rarity">${rarityNames[c.rarity]}${c.sourceBoss?' · ボス固有':''}</span></button>`}
function oldIntentText(e){if(e.bossPart)return '攻撃しない部位 · 破壊でボス弱体化';if(e.intent.kind==='stagger')return '阻止成功 · 次の強攻撃を取り消し';if(e.intent.kind==='heal')return `味方1体をHP${e.intent.value}回復（自分以外）`;if(e.intent.kind==='protect')return `敵全員に防御${e.intent.value}`;return e.intent.kind==='attack'?`攻撃 · ${Math.max(0,Math.round(e.intent.value*(e.weak>0?.75:1)))} ダメージ`:e.intent.kind==='defend'?`防御 · ${e.intent.value} ブロック`:e.intent.kind==='buff'?`強化 · 攻撃力 +${e.intent.value}`:`毒 · ${e.intent.value} 付与`;}
function enemyOverview(){const b=S.battle,alive=b.enemies.filter(e=>e.hp>0),incoming=alive.reduce((sum,e)=>sum+(e.intent.kind==='attack'?Math.round(e.intent.value*(e.weak>0?.75:1))*(e.intent.hits||1):0),0);return `<section class="enemy-overview" aria-label="敵全員の状態と行動"><div class="formation-heading"><strong>敵 ${alive.length} / ${b.enemies.length}体</strong><span>合計攻撃 ${incoming} · 防御後 ${Math.max(0,incoming-b.block)}<small>（毒・反撃を除く）</small></span></div><div class="enemy-roster">${b.enemies.map((e,i)=>`<button class="enemy-status ${i===b.selected?'selected':''} ${e.hp<=0?'defeated':''}" onclick="selectEnemy(${i})" ${e.hp<=0?'disabled':''} aria-pressed="${i===b.selected}" aria-label="${esc(e.name)}を選択"><strong>${i===b.selected?'◆ ':''}${esc(e.name)}</strong>${e.bossPart?'<span class="enemy-role">部位</span>':''}${e.combatRole?`<span class="enemy-role role-${e.combatRole}">${enemyRoles[e.combatRole].name}</span>`:''}<span>HP ${e.hp} / ${e.maxHp} · 防御 ${e.block}</span><b>${e.hp>0?intentText(e):'撃破済み'}</b><small>${e.poison?'毒 '+e.poison+' ':''}${e.bleed?'出血 '+e.bleed+' ':''}${e.weak?'弱体 '+e.weak+' ':''}${e.vuln?'脆弱 '+e.vuln:''}</small></button>`).join('')}</div><small>単体攻撃：敵を選択 ／ 全体攻撃：生存する敵すべて</small></section>`;}
function legacyBattleScreen51(){const b=S.battle,target=b.enemies[b.selected]?.hp>0?b.enemies[b.selected]:b.enemies.find(e=>e.hp>0)||b.enemies[0];return `${replayNotice21()}<div class="combat-shell"><div class="combat-caption"><span>第${S.act+1}階層 · ${actNames[S.act]}</span><span>TURN ${b.turn} / ${nodeInfo[b.type][1]}</span></div><section class="painted-battle scene-${chapters[S.act].color} ${battleFX?'fx-'+battleFX.kind:''}" aria-label="戦闘画面"><div class="combat-vignette"></div><div class="combat-health"><div class="health-panel hero-health"><strong>${classes[S.cls].name}</strong><div class="hp"><div class="hp-fill" style="width:${S.hp/S.maxHp*100}%"></div><span>${S.hp} / ${S.maxHp}</span></div><small>防御 ${b.block} · 筋力 ${b.str}${b.poison?' · 毒 '+b.poison:''}${b.thorns?' · 反撃 '+b.thorns:''}</small></div><div class="health-panel foe-health"><strong>${esc(target.name)}</strong><div class="hp"><div class="hp-fill" style="width:${target.hp/target.maxHp*100}%"></div><span>${target.hp} / ${target.maxHp}</span></div><small>${target.block?'防御 '+target.block+' ':''}${target.poison?'毒 '+target.poison+' ':''}${target.bleed?'出血 '+target.bleed+' ':''}${target.weak?'弱体 '+target.weak+' ':''}${target.vuln?'脆弱 '+target.vuln:''}</small></div></div><div class="battle-energy"><span>✦ エネルギー</span><b>${b.energy} <small>/ ${b.maxEnergy}</small></b><div class="energy-orbs">${Array.from({length:Math.min(8,b.maxEnergy)},(_,i)=>`<i class="${i<b.energy?'lit':''}"></i>`).join('')}</div></div><div class="enemy-intention ${target.intent.kind}"><span>敵の行動〈意図〉</span><b>${intentText(target)}</b></div>${battleFX?`<div class="spell-trace trace-${battleFX.kind}" aria-hidden="true"><i></i><i></i><i></i></div><div class="battle-feedback" role="status">${esc(battleFX.label)} <b>${esc(battleFX.amount)}</b></div>`:''}<div class="painted-actors"><div class="painted-hero ${battleFX?'fx-hero':''}">${characterArt(heroArt(),'hero-body',classes[S.cls].name)}</div><div class="painted-enemies ${b.enemies.length===3?'trio':b.enemies.length===2?'duo':''}">${b.enemies.map((e,i)=>`<button class="painted-enemy ${i===b.selected?'targeted':''} ${e.hp<=0?'fallen':''} ${battleFX?.targets?.includes(i)||battleFX?.target===i?'fx-target':''}" onclick="selectEnemy(${i})" ${e.hp<=0?'disabled':''} aria-label="${esc(e.name)}を対象に選択">${e.bossPart?`<div class="boss-part-art" role="img" aria-label="${esc(e.name)}">✦</div>`:characterArt(enemyArt(e,e.combatRole?'battle':b.type),'enemy-body',e.name)}<span class="enemy-name">${esc(e.name)}${b.enemies.length>1?' · '+e.hp+'/'+e.maxHp:''}</span><span class="target-mark">${i===b.selected?'◆ TARGET':'タップして選択'}</span></button>`).join('')}</div></div><div class="battle-ground"></div><div class="scene-floor-caption">${b.enemies.length>1?'攻撃する敵をタップして選択':'選択中の敵に攻撃します'}</div></section>${enemyOverview()}${bossMechanicPanel()}<div class="hand-banner"><span>❖ あなたの手札</span><small>アタック使用 ${b.attacksPlayed||0}枚 · 選択 → 使用</small></div><div class="hand illustrated-hand">${b.hand.map((id,i)=>renderCard(id,i)).join('')}</div>${supportControls()}${renderCardDock()}<div class="combat-actions"><div class="pile-box"><b>${b.draw.length}</b><span>山札</span></div><div class="pile-box"><b>${b.discard.length}</b><span>捨て札</span></div><span class="muted small">敵の意図を確認して終了</span><div class="pile-box"><b>${b.exhaust.length}</b><span>除外</span></div></div><div class="log">${log.slice(0,3).map(esc).join(' ／ ')||'敵の意図を見て、カードを選びましょう。'}</div></div>`}
function legacyReward58(){const r=S.reward;return `${replayNotice21()}<div class="panel center"><h2>⚔ 勝利！</h2><p class="gold">+${r.gold}G を獲得</p><p>戦闘後回復 HP+${r.recovery||0}${r.hidden?' · 隠しボス撃破：星の護符を獲得':''}</p>${r.source?rewardRateNote(r.source,r.bossName):'<p class="small muted">更新前に抽選済みの報酬です。次の報酬から新しい確率を適用します。</p>'}<p class="muted small">カードをタップして所持カードと比較 → 「このカードを獲得」で決定。選ばずに進むことも可能。</p>${r.relic?`<div class="toast">レリック獲得予定：${relics.find(x=>x[0]===r.relic)?.[2]} ${relics.find(x=>x[0]===r.relic)?.[1]}（カード選択後に獲得）</div>`:''}${r.hidden?'<p class="small gold">報酬を確定すると、「物語」から竜の討伐後の記録を読めます。</p>':''}<div class="reward-grid">${r.options.map(id=>`<section>${renderCard(id,0,'reward')}${adviceHtml19(id)}</section>`).join('')}</div><button class="btn secondary" onclick="finishReward(null)">カードを取らずに進む →</button></div>`}
function legacy45_restScreen(){return `<div class="panel center"><h2>🔥 静寂の焚き火</h2><p class="muted">冷えた石床に火が灯る。ひとときの休息か、戦力の強化か。</p><div class="grid3"><button class="choice" onclick="rest('heal')">❤️ 休息 <br><span class="small">HPを${Math.max(15,Math.round(S.maxHp*.3))}回復する</span></button><button class="choice" onclick="rest('upgrade')">✨ 鍛錬 <br><span class="small">デッキのカード1枚を強化</span></button><button class="choice" onclick="resolveNode()">🚶 何もせず進む<br><span class="small">HP・デッキを変更しない</span></button></div></div>`}
const eventDefs=[['血塗られた宝箱','封じられた箱から金属が擦れる音がする。','HP9を支払い、90G獲得','HP12を回復'],['星屑の祭壇','古い祭壇に祈りが刻まれている。','最大HP+7','45Gを獲得'],['闇の取引','名のない商人が見慣れぬ遺物を差し出した。','HP7を支払い、レリック獲得','HP8を回復'],['死者の市場','亡者たちが価値を交換しようと囁く。','HP10を支払い、65G獲得','ランダムなカード1枚を獲得'],['精霊の泉','石の裂け目から淡い光が溢れている。','HP18を回復','30Gを獲得']];
