function closeModal(){modal=null;render()}function resume(){S=load();modal=null;render()}function restart(){if(S?.campaign)return returnToHub();localStorage.removeItem(SAVE_KEY);S=null;modal=null;render()}function exportSave(){const blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='abyss-chronicle-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
