const PROFILE_KEY='abyss_chronicle_profile_v06';
function readProfile(){try{const p=JSON.parse(localStorage.getItem(PROFILE_KEY));if(p&&Array.isArray(p.achievements)&&Array.isArray(p.history)&&Array.isArray(p.recorded)&&Number.isInteger(p.clears)&&p.clears>=0)return p;}catch{}return {achievements:[],history:[],recorded:[],clears:0};}
let profile=readProfile();
function saveProfile(){localStorage.setItem(PROFILE_KEY,JSON.stringify(profile));}
function unlock(id){if(!profile.achievements.includes(id)){profile.achievements.push(id);saveProfile();}}
function recordRun(clear){if(!S.runId)S.runId=crypto.randomUUID();if(profile.recorded.includes(S.runId))return;profile.recorded.push(S.runId);if(clear){profile.clears++;unlock('clear');}profile.history.unshift({id:S.runId,cls:S.cls,clear,ending:clear?S.story?.ending:null,difficulty:S.difficulty||'standard',extra:!!S.extraCleared,hidden:!!S.hiddenDefeated,wins:S.statistics.wins,turns:S.statistics.turns,date:new Date().toISOString()});profile.history=profile.history.slice(0,20);saveProfile();}
