function cardArt(c){return c.art??oldCardArt(c);}
function enemyArt(e,type){if(/霜冠の守護者/.test(e.name))return 14;if(/記憶喰いの司書/.test(e.name))return 11;if(/黎明を阻む王/.test(e.name))return 6;if(/忘却の竜/.test(e.name))return 7;if(type==='boss')return oldEnemyArt(e,type);const patterns=[/蜘蛛/,/狼|豹/,/樹/,/亡霊/,/蛇|獣/,/狩人/,/巨人|巨像/,/黒炎/];const i=patterns.findIndex(p=>p.test(e.name));return i<0?oldEnemyArt(e,type):8+i;}
function capEliteCaptainHeavy(enemy, state) {
  const difficulty = state.difficulty || 'standard';
  if (difficulty !== 'standard' && difficulty !== 'veteran') return;
  if (state.act < 3 || state.act > 7 || enemy.role !== '隊長') return;
  if (enemy.intent?.kind !== 'attack' || enemy.intent.label !== '強攻撃') return;

  const bonusLimit = 10 + (state.act - 3) * 2;
  enemy.intent.value = Math.min(enemy.intent.value, enemy.atk + bonusLimit);
}
function rollIntent(e,act){act=Math.min(act,7);const damageScale=difficultyRules().attack*(e.stageAttack39||1)*(e.bossAttack41||1)*(e.tuning57?.special||1)*(e.tuning60?.special||1);if(e.bossPart){e.intent={kind:'defend',value:0};e.pattern='部位を破壊するとボスの強化を解除';return;}if(e.combatRole&&e.combatRole!=='striker'){const cycle=e.combatRole==='healer'?['heal','attack','attack']:e.combatRole==='guardian'?['protect','attack','defend']:['charge','heavy','attack'];e.aiStep=Number.isInteger(e.aiStep)?e.aiStep:0;const kind=cycle[e.aiStep++%cycle.length];e.phase=1;e.intent={kind:kind==='heavy'?'attack':kind,value:kind==='heal'?4+act:kind==='protect'?4+act:kind==='charge'?0:kind==='defend'?4+act:kind==='heavy'?e.atk+Math.round((6+act*2)*(e.pressure||1)*damageScale):e.atk,label:kind==='heavy'?'魔力解放':''};e.pattern=cycle.map(k=>({heal:'味方1体回復',protect:'全員に盾',charge:'魔力詠唱',heavy:'魔力解放',attack:'攻撃',defend:'防御'}[k])).join(' → ');return;}const boss=/骸骨王|禁忌の魔女|深淵の君主|星喰い|忘却の竜|灰潮の提督|霜冠の守護者|記憶喰いの司書|黎明を阻む王/.test(e.name);e.phase=boss&&e.hp<=e.maxHp*.5?2:1;e.aiStep=Number.isInteger(e.aiStep)?e.aiStep:0;
let cycle=/霜冠の守護者/.test(e.name)?['defend','attack','charge','heavy']:/記憶喰いの司書/.test(e.name)?['attack','charge','heavy','defend']:/黎明を阻む王/.test(e.name)?['charge','heavy','attack','defend']:/灰潮の提督/.test(e.name)?['defend','poison','charge','heavy']:/忘却の竜/.test(e.name)?['charge','heavy','poison','defend']:/星喰い/.test(e.name)?['attack','charge','heavy','defend']:boss?(act===0?['attack','defend','charge','heavy']:act===1?['poison','attack','charge','heavy']:['defend','attack','charge','heavy']):/蜘蛛|蛇|獣/.test(e.name)?['poison','attack','attack']:/狼|豹|狩人/.test(e.name)?['attack','defend','heavy']:/樹|巨|衛兵|番人|墓守/.test(e.name)?['defend','attack','heavy']:/魔|司祭|預言|亡霊/.test(e.name)?['poison','attack','buff']:['attack','attack','defend'];
if(boss&&act>0&&e.stageAttack39&&e.stageAttack39>1){cycle=cycle.map(k=>k==='defend'?'attack':k);}const pressure=e.pressure||1;if(e.skipHeavy&&cycle[e.aiStep%cycle.length]==='heavy'){e.aiStep++;e.skipHeavy=false;}const kind=cycle[e.aiStep%cycle.length];e.aiStep++;const bonus=e.phase===2?Math.round((3+act)*damageScale):0;e.intent={kind:kind==='heavy'?'attack':kind,value:kind==='charge'?0:kind==='heavy'?e.atk+Math.round((6+act*2)*pressure*damageScale)+bonus:kind==='attack'?e.atk+bonus:kind==='defend'?Math.max(1,Math.round((7+act*4)*pressure)):kind==='buff'?Math.max(1,Math.round(2*pressure)):Math.max(1,Math.round((2+act)*pressure*(e.tuning57?.dot||1))),label:kind==='heavy'?'強攻撃':kind==='charge'?'大技の予告':''};capEliteCaptainHeavy(e,S);e.pattern=cycle.map(k=>({attack:'攻撃',heavy:'強攻撃',defend:'防御',poison:'毒',buff:'強化',charge:'予告'}[k])).join(' → ');}
function intentText(e){return (e.phase===2?'第二形態 · ':'')+(e.intent.kind==='charge'?'構え · 次の行動は強攻撃':(e.intent.label?e.intent.label+' · ':'')+oldIntentText(e));}
const companions=[{id:'noel',name:'斥候ノエル',text:'鐘守の少年は、妹の紋章が刻まれた抜け道を知っていた。旅に同行する代わりに、取り残された人を見捨てないと約束してほしいという。',ability:'手札を2枚引く',kind:'draw'}, {id:'lyra',name:'癒し手リラ',text:'森に残された治療師は、魔女の呪いを解く薬草を集めている。妹だけでなく森の住人も救うなら、最後まで力を貸すと告げた。',ability:'HP6回復・毒を2軽減',kind:'heal'}, {id:'garen',name:'守護者ガレン',text:'黒鎧の兵は剣を伏せた。妹を鍵にしたことを悔やんでいる。償いの機会を与えるか、その鎧だけを受け取るか。',ability:'ブロック12を得る',kind:'block'}];
