function useSupport(){const b=S?.battle,c=activeCompanion();if(S?.screen!=='battle'||!c||b.supportUsed)return;b.supportUsed=true;const bonded=S.quests?.includes(c.id);if(c.kind==='draw')draw(bonded?3:2);if(c.kind==='heal'){heal(bonded?10:6);b.poison=Math.max(0,b.poison-(bonded?4:2));}if(c.kind==='block')b.block+=bonded?18:12;AV.cue(c.kind==='heal'?'heal':c.kind==='block'?'guard':'magic');battleFX={kind:c.kind==='heal'?'heal':c.kind==='block'?'guard':'magic',label:c.name+'の支援',amount:supportText(c),target:-1};log.unshift(c.name+'の支援：'+supportText(c));save();render();}
function supportControls(){const c=activeCompanion(),b=S.battle;return `<div class="support-controls">${c?`<span>${c.name} · ${supportText(c)}</span><button class="btn secondary" onclick="useSupport()" ${b.supportUsed?'disabled':''}>${b.supportUsed?'支援済み':'仲間の支援'}</button>`:'<span>仲間は第1〜3章の事件にランダム配置。再探索でも勧誘できます。</span>'}<details><summary>敵の戦術を見る</summary>${b.enemies.filter(e=>e.hp>0).map(e=>`<p>${esc(e.name)}：${e.combatRole?enemyRoles[e.combatRole].hint+'。':''}${esc(e.pattern||'次の行動から固定順へ移行')}。${b.type==='boss'?'HP半分以下の次の予告から第二形態（攻撃力上昇）。':''}</p>`).join('')}</details></div>`;}
function partyBanner(){const c=activeCompanion();return `<div class="party-banner"><span>同行：${c?c.name:'なし'} · ${S.allies?.length||0}/3人</span><button class="btn secondary" onclick="showModal('allies')">仲間を選ぶ</button><button class="btn secondary" onclick="showModal('archive')">記録・解放</button></div>`;}
function alliesScreen(){return `<h2>仲間と支援</h2><p>同行中の1人が各戦闘1回支援します。同行の変更は戦闘の外で行います。</p>${companions.map(c=>`<div class="item"><b>${c.name}</b><p>${supportText(c)}</p>${S.allies?.includes(c.id)?`<button class="btn secondary" onclick="chooseAlly('${c.id}')" ${S.screen==='battle'||S.activeAlly===c.id?'disabled':''}>${S.activeAlly===c.id?'同行中':'同行する'}</button>`:'<span>未加入 · 第'+(companions.indexOf(c)+1)+'章のイベントにランダム配置</span>'}</div>`).join('')}`;}
function archiveScreen(){return `<h2>クリア記録・アンロック</h2><p>クリア ${profile.clears}回 · 結末 ${new Set(profile.history.filter(r=>r.clear).map(r=>r.ending)).size}/4（直近20件）</p>${[['elite','精鋭を初撃破'],['boss','階層ボスを初撃破'],['clear','初クリア']].map(([id,title])=>`<div class="item"><b>${profile.achievements.includes(id)?'解放済み':'未解放'} · ${title}</b><p>${extraCards.filter(c=>c[6]===id).map(c=>c[1]).join(' / ')}</p></div>`).join('')}<p class="small muted">解放カードは対象職業の報酬・商店に出現します。記録はこのブラウザに保存。冒険の新規開始でも残ります。直近20件を表示します。</p>${profile.history.map(r=>`<div class="item">${r.clear?'CLEAR':'DEFEAT'}${r.extra?' · 第4階層踏破':''}${r.hidden?' · 隠しボス撃破':''} · ${esc(classes[r.cls]?.name||r.cls)} · ${r.ending?esc(endingDefs[r.ending]?.title||r.ending):r.wins+'勝'} · ${esc(r.date.slice(0,10))}</div>`).join('')||'<p>まだ冒険の記録はありません。</p>'}`;}


const difficulties={standard:{name:'標準',hp:1.5,attack:1.4,recovery:1,checkpoint:.25,detail:'道中は高難度。ボスは段階的に強化。戦闘後HP1回復'},veteran:{name:'熟練',hp:1.8,attack:1.7,recovery:0,checkpoint:.22,detail:'さらに高難度。敵の耐久・攻撃を増強。戦闘後回復なし'}};
C.m_study.cost=0;
