function difficultyRules(){const d=difficulties[S?.difficulty]||difficulties.standard;return d;}
function chooseDifficulty(id){if(S||!difficulties[id])return;selectedDifficulty=id;render();}
function difficultyPicker(){return `<section class="panel"><h2>難易度を選択</h2><p class="small muted">冒険開始後は固定。攻撃倍率は強攻撃・第二形態の追加威力にも適用。標準・熟練の2段階。道中は高難度を維持し、ボスは地域ごとに段階的に強くなります。防御・弱体・部位破壊・仲間の支援を使い分けよう。ボスの大技を止めきれない時は、予告を見て防御に備えます。熟練はさらに敵の耐久・攻撃と大技阻止条件が上昇。敗北しても攻略済み地域は残り、拠点から再挑戦できます。</p><div class="grid3">${Object.entries(difficulties).map(([id,d])=>`<button class="choice ${selectedDifficulty===id?'difficulty-selected':''}" aria-pressed="${selectedDifficulty===id}" onclick="chooseDifficulty('${id}')"><b>${selectedDifficulty===id?'✓ ':''}${d.name}</b><small>${d.detail}</small></button>`).join('')}</div></section>`;}
chapters.push({tag:'CHAPTER IV · OPTIONAL',title:'星骸の天文台',intro:'君主の玉座の奥で、星図が淡く光る。深淵を生んだものは、まだ空の向こうを見ていた。仲間と交わした約束が、閉ざされた観測室への鍵になる。',goal:'星喰いの監視者を倒し、夜空に残る傷を閉じる。',color:'stars'});
