const personalQuests=[{id:'noel',title:'ノエルの消えない鐘',text:'ノエルは小さな鐘を握りしめた。瓦礫の下に置いてきた兄の名を、城門に刻みたいという。',reward:'支援のドローが2枚→3枚',a:'兄の名を刻み、鐘を鳴らす',cost:'HP6を失う。ノエルの支援を強化'}, {id:'lyra',title:'リラの最後の薬草',text:'リラは薬草を二つに分けた。故郷へ届けるか、妹を救うために残すか。あなたの答えを待っている。',reward:'支援がHP10回復・毒4軽減に強化',a:'故郷への使者に薬草を託す',cost:'30Gを支払う。リラの支援を強化'}, {id:'garen',title:'ガレンの折れた誓い',text:'観測室の扉には、ガレンがかつて守れなかった者の名が刻まれていた。もう一度、守るために盾を取れるか。',reward:'支援のブロックが12→18',a:'共に名を読み、守る誓いを結ぶ',cost:'HP8を失う。ガレンの支援を強化'}];
function supportText(c){return S.quests?.includes(c.id)?{noel:'手札を3枚引く',lyra:'HP10回復・毒4軽減',garen:'ブロック18を得る'}[c.id]:c.ability;}
function pendingQuest(){return personalQuests.findIndex(q=>S.allies?.includes(q.id)&&!S.quests?.includes(q.id));}
function eventRow43(role){return S.act<3&&Array.isArray(S.eventRows43)?S.eventRows43[role]:[1,2,4][role];}
function legacyNextEvent(){if(S.act===3){if(S.row===2)return 20;const q=pendingQuest();return q>=0?17+q:21;}if(S.row===eventRow43(0)){const q=pendingQuest();if(q>=0)return 17+q;}return S.row===eventRow43(1)?11+S.act:S.row===eventRow43(2)?14+S.act:pick([0,1,2,3,4,5+S.act*2,6+S.act*2]);}
function hiddenEligible(){return S.act===3&&!S.hiddenDefeated&&(S.quests?.length||0)>=2;}
function adventureEventScreen(){if(S.event>=17&&S.event<=19){const q=personalQuests[S.event-17],canPay=q.id!=='lyra'||canSpend53(30);return `<section class="chapter"><div class="eyebrow">仲間専用イベント</div><h1>${q.title}</h1>${companionPortrait28(q.id)}<p>${q.text}</p>${companionTalk28(q.id,true)}<p class="gold">${q.reward}</p></section><div class="branch-choices"><button class="choice" onclick="eventChoice('a')" ${canPay?'':'disabled'}><b>${q.a}</b><small>${q.cost}</small></button><button class="choice" onclick="eventChoice('b')"><b>今は冒険を優先する</b><small>HP10回復。支援は強化されません。追加階層で再会の機会があります。</small></button></div>`;}if(S.event===20)return `<section class="chapter scene-stars"><div class="eyebrow">隠された観測室</div><h1>忘却の竜の封印</h1><p>仲間の約束を二つ果たしたとき、竜の眠る扉が開く。</p><p>達成した仲間の約束：${S.quests?.length||0}/2</p></section><div class="branch-choices"><button class="choice" onclick="eventChoice('a')" ${hiddenEligible()?'':'disabled'}><b>隠しボス「忘却の竜」に挑む</b><small>HP230・基礎攻撃22（難易度補正あり）。勝利報酬：星の護符・カード・金貨。敗北時は出発前の状態で拠点へ。</small></button><button class="choice" onclick="eventChoice('b')"><b>封印を保ち、先へ進む</b><small>HP12回復。通常の結末へ進めます。</small></button></div>`;return `<section class="chapter scene-stars"><h1>星図に残る帰り道</h1><p>星の灯が、妹へ続く道を照らす。もう少しだけ、歩けそうだ。</p></section><button class="choice" onclick="eventChoice('a')">星の灯を受け取る（HP14回復）</button>`;}
function adventureChoice(choice){if(S?.screen!=='event'||!['a','b'].includes(choice))return;const ev=S.event;if(ev>=17&&ev<=19){const q=personalQuests[ev-17];if(!S.allies?.includes(q.id))return;S.quests=S.quests||[];if(choice==='a'){if(S.quests.includes(q.id)||q.id==='lyra'&&!canSpend53(30))return;if(q.id==='lyra')S.gold-=30;else S.hp=Math.max(1,S.hp-(q.id==='noel'?6:8));S.quests.push(q.id);narrative().mercy++;}else heal(10);S.chronicle=S.chronicle||[];S.chronicle.push({act:S.act,event:ev,title:q.title,text:choice==='a'?'約束を果たした。'+q.reward:'今は先へ進むことを選んだ。'});S.lastEvent={title:q.title,text:choice==='a'?q.reward:'HP10回復'};resolveNode();return;}if(ev===20){if(choice==='a'){if(!hiddenEligible())return;beginBattle('elite',{name:'忘却の竜',icon:'🐉',hp:230,atk:22});S.battle.hidden=true;save();render();}else{heal(12);resolveNode();}return;}if(ev===21&&choice==='a'){heal(14);resolveNode();}}
function legacyCrossroadsScreen(){return `<section class="chapter scene-stars"><div class="eyebrow">追加の冒険 · 選択は自由</div><h1>星骸の天文台への階段</h1><p>君主は倒れた。ここで妹と世界の結末を選ぶことも、封印の起源を追って第4階層へ挑むこともできる。</p></section><div class="branch-choices"><button class="choice" onclick="chooseExtra(true)"><b>第4階層へ進む</b><small>最大HPの35%回復。新たな主と隠しボス、仲間の約束が待つ。敗北時は拠点で再挑戦。</small></button><button class="choice" onclick="chooseExtra(false)"><b>ここで結末を選ぶ</b><small>追加階層を通らず、これまで通りエンディングへ。</small></button></div>`;}
function legacyChooseExtra(enter){if(!S||!['crossroads','endingchoice'].includes(S.screen)||S.extraEntered)return;if(enter){S.extraEntered=true;S.act=3;heal(Math.round(S.maxHp*.35));makeMap();S.screen='map';}else S.screen='endingchoice';save();render();}


function copyState(value){return value===undefined?null:JSON.parse(JSON.stringify(value));}
function heroSnapshot(){const t=copyState({...S,campaign:undefined});t.screen='hub';t.battle=null;t.reward=null;t.shop=null;t.event=null;t.hp=t.maxHp;t.row=0;return t;}
function ensureCampaign(){if(S.campaign)return S.campaign;const cleared=[];for(let i=0;i<Math.min(S.act,3);i++)cleared.push(i);if(S.extraCleared)cleared.push(3);S.campaign={version:1,cleared,hiddenDiscovered:!!S.hiddenDefeated||!!S.extraCleared,hiddenDefeated:!!S.hiddenDefeated,failures:0,endings:S.story?.ending?[S.story.ending]:[],home:null,checkpoint:null};S.campaign.home=heroSnapshot();S.campaign.checkpoint=heroSnapshot();return S.campaign;}
function validateSave(t){if(!validateBaseSave(t)||!validRoute45(t))return false;if(t.replay21&&!validReplay21(t.replay21))return false;if(t.eventRows43!=null&&(!Array.isArray(t.eventRows43)||t.eventRows43.length!==3||new Set(t.eventRows43).size!==3||!t.eventRows43.every(r=>[1,2,4].includes(r))))return false;if(t.path19!=null&&!paths19[t.cls]?.some(p=>p.id===t.path19))return false;const c=t.campaign;if(!c)return true;if(c.novel22&&!validNovel22(c.novel22))return false;if(c.epilogue20!=null&&!['dawn','watch'].includes(c.epilogue20))return false;if(c.epilogue20&&!c.cleared?.includes(7))return false;if(c.version!==1||!Array.isArray(c.cleared)||c.cleared.length>chapters.length||new Set(c.cleared).size!==c.cleared.length||!c.cleared.every((a)=>Number.isInteger(a)&&a>=0&&a<chapters.length)||![c.hiddenDiscovered,c.hiddenDefeated].every(v=>typeof v==='boolean')||!Number.isInteger(c.failures)||c.failures<0||!Array.isArray(c.endings)||!c.endings.every(e=>endingDefs[e]))return false;for(const key of ['home','checkpoint']){const h=c[key];if(!h||h.campaign||h.screen!=='hub'||!validateBaseSave(h)||!validRoute45(h))return false;}if(c.cleared.some(a=>a>0&&!c.cleared.includes(a-1)))return false;if(t.routeChoices&&(!Array.isArray(t.routeChoices)||t.routeChoices.length>t.map.length||!t.routeChoices.every((v,r)=>v==null||Number.isInteger(v)&&v>=0&&v<t.map[r]?.length)))return false;return true;}
function regionUnlocked(act){const c=ensureCampaign();return act===0||c.cleared.includes(act-1);}
function settleAtHub(){finishReplay21();const c=ensureCampaign();S.screen='hub';S.hp=S.maxHp;S.battle=null;S.reward=null;S.shop=null;S.event=null;modal=null;c.home=heroSnapshot();c.checkpoint=heroSnapshot();save();render();}
function returnToHub(){if(!S)return;const c=ensureCampaign();if(S.screen==='hub')return;const fromFailure=S.screen==='defeat',fromEnding=S.screen==='victory'||S.screen==='endingchoice'||S.screen==='crossroads';if(!fromEnding){const restored=copyState(c.checkpoint);S={...restored,campaign:c};}finishReplay21();S.screen='hub';S.hp=S.maxHp;S.hiddenDefeated=c.hiddenDefeated;S.extraCleared=c.cleared.includes(3);if(c.hiddenDefeated)takeRelic('star');S.battle=null;S.reward=null;S.shop=null;S.event=null;modal=null;c.home=heroSnapshot();if(fromFailure)S.lastEvent={title:'拠点へ帰還',text:'攻略済み地域を保持。出発前のカード・金貨から再挑戦できます。'};save();render();}
function enterRegion(act){if(S?.screen!=='hub'||!Number.isInteger(act)||act<0||act>=chapters.length||!regionUnlocked(act))return;const c=ensureCampaign();beginReplay21(c.cleared.includes(act));c.home=heroSnapshot();S.act=act;S.extraEntered=act>=3||!!S.extraEntered;S.screen='map';S.hp=S.maxHp;S.lastEvent=null;makeMap();c.checkpoint=heroSnapshot();save();render();}
function enterHidden(){if(S?.screen!=='hub')return;const c=ensureCampaign();if(!c.hiddenDiscovered||(S.quests?.length||0)<2)return;beginReplay21(c.hiddenDefeated);c.home=heroSnapshot();c.checkpoint=heroSnapshot();S.act=3;S.extraEntered=true;beginBattle('elite',{name:'忘却の竜',icon:'🐉',hp:230,atk:22});S.battle.hidden=true;S.battle.hubReturn=true;save();render();}
function openCampaignEnding(){if(S?.screen!=='hub'||!ensureCampaign().cleared.includes(2))return;S.screen='endingchoice';S.act=3;save();render();}
function chooseExtra(enter){if(!S||!['crossroads','endingchoice'].includes(S.screen))return;if(enter){const c=ensureCampaign();if(!c.cleared.includes(2))return;S.screen='hub';enterRegion(3);}else{S.screen='endingchoice';save();render();}}
function crossroadsScreen(){return `<section class="chapter"><h1>拠点への帰還</h1><p>本編の地域攻略が保存されました。拠点から追加階層や結末を選べます。</p></section><button class="btn" onclick="returnToHub()">拠点へ戻る</button>`;}
function prepareNewJourney(){S=null;modal=null;render();}
function legacyHub56(){const c=ensureCampaign(),q=S.quests?.length||0;return `<section class="chapter scene-stars"><div class="eyebrow">BASE CAMP · 冒険の拠点</div><h1>灯火の宿営地</h1><p>攻略した地域は保存されています。地域を選んで出発し、未発見の道や仲間との約束を探そう。</p><div class="quest">地域攻略 ${c.cleared.length}/${chapters.length} · 仲間の約束 ${q}/3 · 結末 ${c.endings.length}/4 · 敗北 ${c.failures}回</div></section>${expeditionEnding20()}${campAccess33()}${partyBanner()}${pathPanel19()}<p class="small muted">攻略済み地域と討伐済み隠しボスの再探索は練習用。金貨・カード・レリック・最大HP・カード強化・依頼進行は持ち帰れません。未完了の物語や仲間の約束は進められます。</p>${S.lastEvent?`<div class="event-receipt" role="status"><strong>${esc(S.lastEvent.title)}</strong><span>${esc(S.lastEvent.text)}</span></div>`:''}<div class="actions"><button class="btn" onclick="showModal('contracts')">依頼掲示板</button><button class="btn secondary" onclick="showModal('catalog')">カード図鑑 ${Object.keys(C).length}種類</button></div><div class="event-receipt"><strong>拠点で全回復</strong><span>地域内の進行は自動保存。敗北・撤退では、その地域の出発前のカード・金貨に戻ります。攻略済み地域と倒した隠しボスの記録は残ります。</span></div><div class="section-label"><h2>進む地域を選ぶ</h2><button class="btn secondary" onclick="showModal('newjourney')">別の職業で新しい旅</button></div><div class="region-grid">${chapters.map((ch,i)=>{const open=regionUnlocked(i),clear=c.cleared.includes(i);return `<button class="region-card ${clear?'cleared':''}" onclick="enterRegion(${i})" ${open?'':'disabled'}><span class="eyebrow">REGION ${i+1} · ${clear?'攻略済み':open?'挑戦可能':'未解放'}</span><h3>${ch.title}</h3><p>${ch.goal}</p><small>${open?clear?'再探索する · 育成報酬の持ち帰りなし':'この地域へ出発する':'前の地域を攻略すると解放'}</small></button>`}).join('')}</div><section class="panel"><h2>隠された観測室</h2>${c.hiddenDiscovered?'<button class="btn secondary" onclick="showModal(\'dragon31\')">竜の記録を読む</button>':''}<p>${c.hiddenDefeated?'忘却の竜：討伐済み。再戦は練習用。育成報酬の持ち帰りはありません。星の護符と討伐記録は保持。':c.hiddenDiscovered?'忘却の竜を発見。仲間2人の約束を果たすと、拠点から直接挑めます。':'第4地域の観測室、または第4地域の主を攻略すると場所が判明します。'}</p><p class="small gold">仲間の約束：${q}/2 · ノエル／リラ／ガレンの専用イベントで達成</p><button class="btn" onclick="enterHidden()" ${!c.hiddenDiscovered||q<2?'disabled':''}>${c.hiddenDefeated?'忘却の竜と再戦する':'忘却の竜へ直接挑む'}</button></section>${c.cleared.includes(2)?`<section class="panel"><h2>妹と世界の結末</h2><p>エンディング後も拠点へ戻り、追加地域や未完了の探索を続けられます。</p><button class="btn" onclick="openCampaignEnding()">結末を選ぶ</button></section>`:''}`;}
function previousNextEvent(){if(S.act<3&&S.row===eventRow43(1)&&S.story?.decisions.some(d=>d.chapter===S.act))return 21;if(S.act<3&&S.row===eventRow43(2)&&S.allies?.includes(companions[S.act].id))return 21;const ev=legacyNextEvent();if(ev===20)ensureCampaign().hiddenDiscovered=true;return ev;}
const routeDetails={treasure:'宝箱を開き、金貨かカードを選ぶ。開封済みの箱は再取得できません。',battle:'通常の敵と戦闘。勝利で金貨・カードと戦闘後回復。',elite:'強敵。通常より危険ですが、勝利でレリックを獲得。',event:'物語の分岐や仲間との約束。選択によって恩恵と代償が変わります。',rest:'回復・カード強化・1枚無料削除から1つ選択。',shop:'金貨でカード・レリック・回復を購入。カード削除もできます。',boss:'地域の主との決戦。勝つと攻略を記録し、拠点へ帰還。'};
function routePosition(row,index){return (index+.5)/S.map[row].length;}
function routeLinked(row,a,b){return S.route45?S.route45.links[row]?.some(e=>e[0]===a&&e[1]===b)||false:Math.abs(routePosition(row,a)-routePosition(row+1,b))<.51;}
function routeAvailable(row,index){if(row!==S.row)return false;if(row===0||S.routeChoices?.[row-1]==null)return true;return routeLinked(row-1,S.routeChoices[row-1],index);}
function inspectRoute(row,index){readerStack56=[];if(!S||S.screen!=='map'||!S.map[row]?.[index])return;modal={type:'route',row,index};render();}
function legacy45_routePreview(row,index){const type=S.map[row][index],available=routeAvailable(row,index),taken=S.routeChoices?.[row]===index;return `<h2>${row+1}段目 · ${nodeInfo[type][1]}</h2><p>${routeDetails[type]}</p><p class="gold">${row<S.row?taken?'通過した道':'今回は通らなかった道':available?'現在地から進めます':row===S.row?'現在の道からは進めません':'先の候補。直前のマスと線でつながる道へ進めます。'}</p>${row<5?`<p>この先：${S.map[row+1].map((t,j)=>routeLinked(row,index,j)?nodeInfo[t][1]:null).filter(Boolean).join(' ／ ')}</p>`:''}${available?`<button class="btn" onclick="closeModal();enterNode(${index})">ここへ進む</button>`:''}`;}
function legacy45_routeGraph(){const h=624,gap=100,top=48;let lines='';for(let r=0;r<5;r++)for(let i=0;i<S.map[r].length;i++)for(let j=0;j<S.map[r+1].length;j++)if(routeLinked(r,i,j)){const done=S.routeChoices?.[r]===i&&S.routeChoices?.[r+1]===j;lines+=`<line x1="${routePosition(r,i)*360}" y1="${top+r*gap}" x2="${routePosition(r+1,j)*360}" y2="${top+(r+1)*gap}" class="${done?'trail-done':r===S.row?'trail-next':''}"/>`;}return `<div class="route-legend"><span>● 現在地</span><span>金枠：進める道</span><span>✓ 通過済み</span><span>先のマス：タップで詳細</span></div><div class="route-map" aria-label="地域の全ルート"><svg viewBox="0 0 360 ${h}" preserveAspectRatio="none" aria-hidden="true">${lines}</svg>${S.map.map((row,r)=>`<div class="route-map-row" style="top:${top+r*gap}px"><span class="route-step-label">${r+1}</span>${row.map((type,i)=>{const taken=S.routeChoices?.[r]===i,available=routeAvailable(r,i);return `<button class="route-map-node ${available?'available':''} ${taken?'taken':''} ${r===S.row?'current-row':''} ${r<S.row&&!taken?'missed':''}" style="left:${routePosition(r,i)*100}%" onclick="inspectRoute(${r},${i})" aria-label="${r+1}段目 ${nodeInfo[type][1]} ${taken?'通過済み':available?'進める':'詳細を見る'}"><span>${taken&&r<S.row?'✓':nodeInfo[type][0]}</span><b>${nodeInfo[type][1]}</b>${r===S.row?'<small>現在地からの候補</small>':''}</button>`}).join('')}</div>`).join('')}</div>`;}
function legacy45_mapScreen(){const ch=chapters[S.act];return `${replayNotice21()}<section class="route-heading"><div class="eyebrow">REGION ${S.act+1} · ${S.row+1}/6段目 · ${difficulties[S.difficulty||'standard'].name}</div><h1>${ch.title}</h1><p>${ch.goal}</p>${S.preparation46?`<p class="gold">準備中：${trailPeople46[S.preparation46.kind].name}の支援 · 次の1戦で消費</p>`:''}<details><summary>物語と今回の目的</summary><p>${ch.intro}</p></details></section>${S.lastEvent?`<div class="event-receipt"><strong>${esc(S.lastEvent.title)}</strong><span>${esc(S.lastEvent.text)}</span></div>`:''}<div class="section-label"><h2>現在地 ${S.row+1}/6 · どの道を進む？</h2><button class="btn secondary" onclick="showModal('retreat')">拠点へ撤退</button></div><p class="route-balance-note">新規探索の配分：通常／強戦闘を2回＋ボス戦。宝箱は最大1回。4段目は通常戦か強戦闘、5段目は休息かイベント。仲間との出会いは第1〜3章の2・3・5段目のイベントに出発ごとにランダム配置。</p>${routeGraph()}<section class="panel route-current"><h2>今、進める場所</h2><div class="route-choices">${S.map[S.row].map((type,i)=>routeAvailable(S.row,i)?`<button class="route-choice ${type}" onclick="enterNode(${i})"><span class="route-icon">${nodeInfo[type][0]}</span><span><b>${nodeInfo[type][1]}</b><small>${routeDetails[type]}</small></span><span class="route-arrow">→</span></button>`:'').join('')}</div></section>`;}


