function legacy45_nextEvent(){if(S.act>=5){const q=pendingQuest();if(S.row===1&&q>=0)return 17+q;return 24+(S.act-5)*2+(S.row===2?0:1);}if(S.act===4){const q=pendingQuest();if(S.row===1&&q>=0)return 17+q;return S.row===2?22:23;}return previousNextEvent();}
function legacy45_treasureScreen(){return `${replayNotice21()}<section class="chapter"><div class="eyebrow">TREASURE · 第${S.act+1}地域</div><h1>忘れられた宝箱</h1><p>金貨袋と、古いカードが収められている。どちらか一つだけ持ち帰れる。</p></section><div class="panel center"><button class="btn" onclick="takeTreasure('gold')">金貨${40+S.act*5}Gを取る</button><h2>または、カードを1枚選ぶ</h2>${rewardRateNote('treasure')}<div class="reward-grid">${S.treasure.options.map(id=>renderCard(id,0,'treasure')).join('')}</div></div>`;}
function legacy45_takeTreasure(kind,id){if(S?.screen!=='treasure'||!S.treasure)return;if(kind==='gold')S.gold+=40+S.act*5;else if(kind==='card'&&S.treasure.options.includes(id))S.deck.push(id);else return;S.statistics.chests=(S.statistics.chests||0)+1;S.lastEvent={title:'宝箱を開いた',text:kind==='gold'?`${40+S.act*5}Gを獲得`:C[id].name+'を獲得'};S.treasure=null;resolveNode();}
function portEventScreen(){const e=S.event===22;return `<section class="chapter scene-harbor"><div class="eyebrow">灰燼の港 · 選択</div><h1>${e?'帰還船の航海日誌':'灯台の避難民'}</h1><p>${e?'沈没船の船室に、提督が隠した航路図が残っていた。危険を冒して調べるか、岸へ運ぶか。':'港の住民が灯台の陰に避難している。食料を分けるか、安全な道だけ伝えるか。'}</p></section><div class="branch-choices"><button class="choice" onclick="portChoice('a')" ${!e&&!canSpend53(30)?'disabled':''}><b>${e?'深く調べる（HP8を失う・真相+1・新カード獲得）':'食料を分ける（30G・HP16回復・絆+1）'}</b></button><button class="choice" onclick="portChoice('b')"><b>${e?'岸に運ぶ（45G獲得）':'安全な道を伝える（HP8回復）'}</b></button></div>`;}
function portChoice(choice){if(S?.screen!=='event'||![22,23].includes(S.event)||!['a','b'].includes(choice))return;const e=S.event;if(e===22){if(choice==='a'){S.hp=Math.max(1,S.hp-8);narrative().truth++;S.deck.push(pick(cardPool().filter(c=>c.newCard)).id);}else S.gold+=45;}else if(choice==='a'){if(!canSpend53(30))return;S.gold-=30;heal(16);narrative().mercy++;}else heal(8);S.chronicle=S.chronicle||[];S.chronicle.push({act:S.act,event:e,title:e===22?'帰還船の航海日誌':'灯台の避難民',text:choice==='a'?'危険と代償を引き受け、人々のために動いた。':'安全な帰路を優先した。'});resolveNode();}
const contractDefs=[{id:'road',name:'街道の安全を取り戻せ',stat:'wins',goal:3,reward:80,desc:'受注後、戦闘で3勝する'}, {id:'cache',name:'忘れられた宝を探せ',stat:'chests',goal:2,reward:70,desc:'受注後、宝箱を2個開ける'}, {id:'lord',name:'地域の主への挑戦',stat:'bosses',goal:1,reward:100,desc:'受注後、地域の主を1体倒す（再探索でも可）'}];
function contractList(){const c=ensureCampaign();if(!c.contracts)c.contracts=[];return c.contracts;}
function contractProgress(def,entry){return Math.max(0,(S.statistics[def.stat]||0)-entry.base);}
function acceptContract(id){if(S?.screen!=='hub')return;const def=contractDefs.find(d=>d.id===id);if(!def||contractList().some(q=>q.id===id))return;contractList().push({id,base:S.statistics[def.stat]||0,claimed:false});save();render();}
function claimContract(id){if(S?.screen!=='hub')return;const def=contractDefs.find(d=>d.id===id),entry=contractList().find(q=>q.id===id);if(!def||!entry||entry.claimed||contractProgress(def,entry)<def.goal)return;const card=pick(cardPool().filter(c=>c.newCard));if(!card)return;entry.claimed=true;entry.rewardCard=card.id;S.gold+=def.reward;S.deck.push(card.id);S.lastEvent={title:'依頼達成：'+def.name,text:`${def.reward}Gと新カード「${card.name}」を獲得`};modal=null;settleAtHub();modal={type:'contractreceipt',id};render();}
function contractsScreen(){return `<h2>依頼掲示板</h2><p>各依頼はこの冒険で1回。受注後の進行で達成し、拠点で報酬を受け取ります。敗北・撤退で失った地域内の進行は達成数にも残りません。</p>${contractDefs.map(d=>{const q=contractList().find(q=>q.id===d.id),p=q?contractProgress(d,q):0;return `<div class="item"><h3>${d.name}</h3><p>${d.desc} · 報酬${d.reward}G＋新カード1枚</p>${q?.claimed&&q.rewardCard?`<div class="contract-receipt"><b>獲得済み：${d.reward}G ＋ ${esc(C[q.rewardCard].name)}</b><p>${esc(cardText(cardDetail(q.rewardCard)))}</p><button class="btn secondary" onclick="showContractReceipt('${d.id}')">獲得内容を見る</button></div>`:''}<p class="gold">${q?q.claimed?'報酬受取済み':Math.min(p,d.goal)+' / '+d.goal:'未受注'}</p><button class="btn secondary" onclick="${q?`claimContract('${d.id}')`:`acceptContract('${d.id}')`}" ${S.screen!=='hub'||q&&(q.claimed||p<d.goal)?'disabled':''}>${q?q.claimed?'達成済み':'報酬を受け取る':'受注する'}</button></div>`}).join('')}`;}
let catalogClass='all',catalogNew=true;
function setCatalogClass(value){if(!['all','warrior','rogue','mage','occult','neutral'].includes(value))return;catalogClass=value;render();}
function toggleCatalogNew(){catalogNew=!catalogNew;render();}
function catalogScreen(){const cards=Object.values(C).filter(c=>(catalogClass==='all'||c.cls===catalogClass)&&(!catalogNew||c.expansion==='0.44'));return `<h2>カード図鑑 · 全${Object.keys(C).length}種類</h2><p>今回追加：守備・状態異常・連携をつなぐ32種類。4職業に各6種類＋共通8種類。通常戦・精鋭戦・宝箱・商店で入手できます。全334種類（ボス固有6種類を含む）。ボス固有カードは対応ボスの報酬限定です。</p><div class="catalog-controls"><label>職業 <select onchange="setCatalogClass(this.value)">${[['all','すべて'],['warrior','騎士'],['rogue','暗殺者'],['mage','魔導士'],['occult','呪術師'],['neutral','共通']].map(([id,n])=>`<option value="${id}" ${id===catalogClass?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn secondary" aria-pressed="${catalogNew}" onclick="toggleCatalogNew()">${catalogNew?'新カード32種を表示中':'全カードを表示中'}</button></div><p>表示 ${cards.length}種類</p><div class="catalog-grid">${cards.map(c=>`<div class="item rarity-${c.rarity}"><b>${c.newCard?'NEW · ':''}${esc(c.name)}</b><p class="small gold">${c.cls==='neutral'?'共通':classes[c.cls].name} · ${c.cost}EN · ${rarityNames[c.rarity]}</p><p>${esc(cardText(c))}</p>${c.sourceBoss?`<small class="boss-source">入手先：${esc(c.sourceBoss)}の報酬限定</small>`:c.unlock?'<small>条件達成で解放</small>':''}</div>`).join('')}</div>`;}


