const bossTactics={
'骸骨王':{summon:'guardian',title:'王の近衛',hint:'最初の大技予告で盾役を1体召喚。全体攻撃でまとめて削るか、盾役を優先して倒そう。'},
'禁忌の魔女':{summon:'healer',title:'禁忌の使い魔',hint:'最初の大技予告で回復役を1体召喚。回復役を倒すと長期戦を防げる。'},
'深淵の君主':{summon:'caster',title:'深淵の伝令',hint:'最初の大技予告で魔法役を1体召喚。詠唱とボスの大技の両方に備えよう。'},
'星喰いの監視者':{part:'星鎖の核',title:'星鎖の障壁',hint:'核が残る間は毎ターン開始時に防御6。核を壊すと防御解除・攻撃力25%低下・脆弱2。'},
'灰潮の提督':{part:'灰潮の砲台',title:'装甲砲台',hint:'砲台が残る間は毎ターン開始時に防御6。砲台を壊すと防御解除・攻撃力25%低下・脆弱2。'},
'忘却の竜':{part:'竜の封印角',title:'封印角の加護',hint:'角が残る間は毎ターン開始時に防御6。角を壊すと防御解除・攻撃力25%低下・脆弱2。'}
};
function initBossMechanics(b){const tactic=bossTactics[b.enemies[0].name];if(!tactic)return;b.bossMechanic={summoned:false,partBroken:false,telegraph:null};if(tactic.part){const part=enemyMake({name:tactic.part,hp:Math.round((24+S.act*5)*difficultyRules().hp*(b.enemies[0].stageAttack39>1?stageRules36().hp:1)),atk:0});part.bossPart=true;tuneEnemy57(part,S,'part',b.tuningHidden57||b.hidden);rollIntent(part,S.act);b.enemies.push(part);b.enemies[0].block+=6;}prepareBossTelegraph(b);}
function bossStaggerNeed39(b){if((S?.difficulty||'standard')==='standard'&&S.act>=2&&!b?.hidden&&!b?.tuningHidden57)return stagger57[S.act];return (S?.difficulty==='veteran'?24:18)+S.act*(S?.difficulty==='veteran'?6:5);}
function prepareBossTelegraph(b){const m=b?.bossMechanic;if(!m)return;const boss=b.enemies[0],tactic=bossTactics[boss.name];if(boss.hp<=0)return;if(!tactic)return;if(tactic.part&&!m.partBroken&&b.enemies.some(e=>e.bossPart&&e.hp>0))boss.block+=b.turn>1?6:0;if(boss.intent.kind==='charge'){m.telegraph={damage:0,needed:bossStaggerNeed39(b),stopped:false};if(tactic.summon&&!m.summoned){const role=tactic.summon,d=difficultyRules(),escort=enemyMake({name:tactic.title,hp:Math.round((20+S.act*6)*d.hp),atk:Math.max(1,Math.round((4+S.act*2)*d.attack))});const stage=boss.stageAttack39>1?stageRules36():{hp:1,attack:1};escort.hp=escort.maxHp=Math.round(escort.maxHp*stage.hp);escort.atk=Math.round(escort.atk*stage.attack);escort.stageAttack39=stage.attack;escort.combatRole=role;escort.pressure=.5;escort.aiStep=0;tuneEnemy57(escort,S,'escort',b.tuningHidden57||b.hidden);rollIntent(escort,S.act);b.enemies.push(escort);m.summoned=true;log.unshift(`${boss.name}が${tactic.title}を召喚`);}}else if(boss.intent.kind!=='stagger')m.telegraph=null;}
function trackBossStagger(enemy,damage){const b=S?.battle,m=b?.bossMechanic,t=m?.telegraph;if(!t||t.stopped||enemy!==b.enemies[0]||enemy.intent.kind!=='charge')return;t.damage+=damage;if(t.damage>=t.needed){t.stopped=true;enemy.intent={kind:'stagger',value:0};enemy.skipHeavy=true;log.unshift('大技の阻止に成功。次の強攻撃を取り消した。');}}
function updateBossParts(b){const m=b?.bossMechanic;if(!m||m.partBroken)return;if(b.enemies.some(e=>e.bossPart&&e.hp<=0)){m.partBroken=true;const boss=b.enemies[0];boss.block=0;boss.atk=Math.max(1,Math.round(boss.atk*.75));if(boss.intent.kind==='attack')boss.intent.value=Math.round(boss.intent.value*.75);boss.vuln=Math.max(2,boss.vuln);log.unshift('部位破壊！ ボスの防御解除・攻撃力低下・脆弱2。');}}
function bossMechanicPanel(){const b=S.battle,m=b?.bossMechanic;if(!m)return '';const tactic=bossTactics[b.enemies[0].name],t=m.telegraph;if(!tactic)return '';return `<section class="boss-mechanic" aria-label="ボス攻略"><strong>ボス攻略 · ${tactic.title}</strong><p>${tactic.hint}</p>${t?`<p class="gold">${t.stopped?'大技の阻止成功！ 次の強攻撃は取り消し。':`大技阻止：この予告中にボスへ攻撃でHPダメージ ${Math.min(t.damage,t.needed)} / ${t.needed}（防御で防がれた分・毒・出血は除く）`}</p>`:'<p>大技の予告中は集中攻撃で阻止できます。阻止できない場合は防御・弱体で備えよう。</p>'}${m.partBroken?'<p class="gold">部位破壊済み · ボスの攻撃力25%低下</p>':''}${m.summoned?'<p>護衛の召喚はこの戦闘で1回。ボスを倒せば護衛・部位が残っていても勝利。</p>':''}</section>`;}
let deckFilter='all',deckSort='cost';
function cardTags(card){const e=card.effect,t=[];if(card.type==='attack')t.push('attack');if(e.block||e.passiveBlock||e.thorns||e.guardBlock||e.paidBlock)t.push('defense');if(e.poison||e.allPoison||e.existingPoison||e.poisonBonus||e.poisonHit||e.detonate)t.push('poison');if(e.bleed||e.bleedHit)t.push('bleed');if(e.draw||e.energy||e.nextEnergy)t.push('draw');if(e.heal||e.passiveHeal)t.push('heal');if(e.poisonHit||e.bleedHit||e.weakHit||e.guardHit||e.comboHit||e.guardDraw||e.detonate||e.blockDamageCap||e.intentHit||e.comboBlock||e.existingPoison)t.push('synergy');return t;}
const deckTagNames={all:'すべて',attack:'攻撃',defense:'防御・反撃',poison:'毒',bleed:'出血',draw:'ドロー・EN',heal:'回復',synergy:'連携'};
function setDeckFilter(value){if(!deckTagNames[value])return;deckFilter=value;render();}
function setDeckSort(value){if(!['cost','name','rarity','type'].includes(value))return;deckSort=value;render();}
function groupedDeck(){const groups=[...new Set(S.deck)].map(id=>({id,count:S.deck.filter(x=>x===id).length,card:cardDetail(id)})).filter(g=>deckFilter==='all'||cardTags(g.card).includes(deckFilter));return groups.sort((a,b)=>deckSort==='cost'?a.card.cost-b.card.cost||a.card.name.localeCompare(b.card.name,'ja'):deckSort==='rarity'?['rare','uncommon','common'].indexOf(a.card.rarity)-['rare','uncommon','common'].indexOf(b.card.rarity):deckSort==='type'?({attack:0,skill:1,power:2,curse:3}[a.card.type]-{attack:0,skill:1,power:2,curse:3}[b.card.type])||a.card.cost-b.card.cost:a.card.name.localeCompare(b.card.name,'ja'));}
function legacy45_deckScreen(removing=false){const groups=groupedDeck(),counts=Object.keys(deckTagNames).filter(k=>k!=='all').map(k=>`${deckTagNames[k]} ${S.deck.filter(id=>cardTags(C[id]).includes(k)).length}`).join(' · ');return `<h2>デッキ整理 · ${S.deck.length}枚 / ${new Set(S.deck).size}種類</h2><p class="small">${counts}</p><p class="small">平均コスト ${(S.deck.reduce((n,id)=>n+C[id].cost,0)/S.deck.length).toFixed(1)}EN。分類は重複します。同名カードは強化済み・未強化を分けて表示。</p><div class="deck-controls"><label>分類 <select onchange="setDeckFilter(this.value)">${Object.entries(deckTagNames).map(([id,name])=>`<option value="${id}" ${deckFilter===id?'selected':''}>${name}</option>`).join('')}</select></label><label>並び順 <select onchange="setDeckSort(this.value)">${[['cost','コスト順'],['name','名前順'],['rarity','レアリティ順'],['type','種類順']].map(([id,name])=>`<option value="${id}" ${deckSort===id?'selected':''}>${name}</option>`).join('')}</select></label></div><p>表示 ${groups.reduce((n,g)=>n+g.count,0)}枚 / ${groups.length}種類</p><p class="small muted">カード削除は拠点・商店で65G／枚。最低5枚は残します。確認画面で決定するまで削除しません。</p><div class="card-list">${groups.map(({id,count,card:c})=>`<div class="item rarity-${c.rarity}"><b>${esc(c.name)}${c.up?'＋':''} ×${count}</b><p class="small gold">${c.cost}EN · ${rarityNames[c.rarity]} · ${cardTags(c).map(k=>deckTagNames[k]).join('／')}</p><p>${esc(cardText(c))}</p>${removeServiceAvailable45()?`<button class="btn small secondary" onclick="requestRemoveCard('${id}')" ${canRemoveCard()?'':'disabled'}>1枚削除を確認（65G）</button>`:''}</div>`).join('')||'<p>この分類のカードはありません。</p>'}</div>`;}
function legacy45_removeConfirmation(){const id=modal.id,c=cardDetail(id);return `<h2>カードを1枚削除しますか？</h2><p>${esc(c.name)} · 所持 ${S.deck.filter(x=>x===id).length}枚</p><p>${esc(cardText(c))}</p><p>65Gを支払い、デッキ ${S.deck.length}枚 → ${S.deck.length-1}枚。残金 ${S.gold-65}G。</p><button class="btn" onclick="confirmRemoveCard()" ${canRemoveCard()?'':'disabled'}>65Gで1枚削除</button><button class="btn secondary" onclick="showModal('deck')">デッキへ戻る</button>`;}
function previewReward(id){if(S?.screen!=='reward'||!S.reward.options.includes(id))return;const tags=cardTags(C[id]),ids=[...new Set(S.deck)];ids.sort((a,b)=>{const score=x=>cardTags(C[x]).filter(t=>tags.includes(t)).length*3+(C[x].type===C[id].type?2:0)-(Math.abs(C[x].cost-C[id].cost));return score(b)-score(a);});modal={type:'compare',id,reference:S.deck.includes(id)?id:ids[0]};render();}
function setComparison(id){if(modal?.type!=='compare'||!S.deck.includes(id))return;modal.reference=id;render();}
function comparisonSetup(card){const e=card.effect,needs=[];if(e.poisonHit||e.detonate)needs.push(['毒',x=>x.poison||x.allPoison]);if(e.bleedHit)needs.push(['出血',x=>x.bleed]);if(e.weakHit)needs.push(['弱体',x=>x.weak||x.allWeak]);if(e.guardHit||e.guardDraw)needs.push(['防御',x=>x.block||x.passiveBlock]);if(e.comboHit)needs.push(['アタック',(_,c)=>c.type==='attack']);return needs.map(([name,predicate])=>`${name}の準備になる所持カード：${S.deck.filter(id=>predicate(C[id].effect,C[id])).length}枚`).join(' ／ ');}
function confirmRewardSelection(){if(modal?.type!=='compare'||S?.screen!=='reward'||!S.reward.options.includes(modal.id))return;finishReward(modal.id);}
function rewardComparison(){const id=modal.id,c=cardDetail(id),reference=modal.reference,owned=cardDetail(reference),count=S.deck.filter(x=>baseCard54(x)===baseCard54(id)).length;return `<h2>報酬カードを比較</h2><p>候補を確認してから獲得を決定できます。強化状態を反映しています。</p><div class="comparison-grid"><section class="panel"><h3>獲得候補 · ${esc(c.name)}${c.up?'＋':''}</h3><p class="gold">${c.cost}EN · ${rarityNames[c.rarity]}</p><p>${esc(cardText(c))}</p>${adviceHtml19(id)}<p>同名カードを${count}枚所持 → 獲得後${count+1}枚</p><p class="small">${comparisonSetup(c)||'他のカードの効果も見て、必要な役割を補おう。'}</p></section><section class="panel"><h3>比較する所持カード</h3><label>所持カード <select onchange="setComparison(this.value)">${[...new Set(S.deck)].map(x=>`<option value="${x}" ${x===reference?'selected':''}>${esc(C[x].name)}${isUpgraded(x)?'＋':''} ×${S.deck.filter(v=>v===x).length}</option>`).join('')}</select></label><p><b>${esc(owned.name)}${owned.up?'＋':''}</b> · ${owned.cost}EN · ${rarityNames[owned.rarity]}</p><p>${esc(cardText(owned))}</p><p class="small">${cardTags(owned).map(k=>deckTagNames[k]).join('／')}</p></section></div><div class="actions"><button class="btn" onclick="confirmRewardSelection()">このカードを獲得</button><button class="btn secondary" onclick="closeModal()">候補一覧へ戻る</button></div>`;}

