function expeditionEvent20(){const e=events20[S.event-24];return `<section class="chapter scene-${chapters[S.act].color}"><div class="eyebrow">遠征編 · ${chapters[S.act].title}</div><h1>${e.title}</h1><p>${e.text}</p></section><div class="branch-choices"><button class="choice" onclick="eventChoice('a')" ${(e.cost&&!canSpend53(e.cost))||(S.event===25&&!upgradeableCards39().length)?'disabled':''}>${e.a}</button><button class="choice" onclick="eventChoice('b')">${e.b}</button></div>`;}
