function chooseEpilogue20(id){if(S?.screen!=='hub'||!ensureCampaign().cleared.includes(7)||S.campaign.epilogue20||!epilogues20[id])return;S.campaign.epilogue20=id;save();render();}


function showContractReceipt(id){if(S?.screen!=='hub')return;const q=contractList().find(q=>q.id===id);if(!q?.claimed||!C[q.rewardCard])return;modal={type:'contractreceipt',id};render();}
function contractReceipt(){const d=contractDefs.find(d=>d.id===modal.id),q=contractList().find(q=>q.id===modal.id);if(!d||!q?.claimed||!C[q.rewardCard])return '<h2>報酬の記録がありません</h2>';const c=cardDetail(q.rewardCard);return `<section class="contract-receipt" role="status" aria-live="polite"><p class="eyebrow">QUEST REWARD</p><h2>依頼報酬を獲得しました</h2><h3>${esc(d.name)}</h3><p class="reward-amount">金貨 ＋${d.reward}G</p><p>現在の所持金：${S.gold}G</p><div class="panel rarity-${c.rarity}"><p>獲得カード · デッキに追加済み</p><h3>${esc(c.name)}${c.up?'＋':''}</h3><p class="gold">${rarityNames[c.rarity]} · ${c.cost}EN</p><p>${esc(cardText(c))}</p><p>同名カードを${S.deck.filter(id=>id===c.id).length}枚所持</p></div><p class="small muted">報酬は自動保存済み。確認画面を閉じても失われません。</p><button class="btn" onclick="showModal('contracts')">依頼掲示板へ戻る</button></section>`;}


const replayFields21=['gold','maxHp','deck','upgraded','relics','statistics','preparation46','cardCopies54'];
function validReplay21(r){return r&&Number.isFinite(r.gold)&&r.gold>=0&&Number.isFinite(r.maxHp)&&r.maxHp>=1&&Array.isArray(r.deck)&&r.deck.length>0&&r.deck.every(id=>C[id])&&Array.isArray(r.upgraded)&&r.upgraded.every(id=>C[id])&&Array.isArray(r.relics)&&r.relics.every(id=>relics.some(x=>x[0]===id))&&r.statistics&&['wins','turns','cards','elites'].every(k=>Number.isFinite(r.statistics[k])&&r.statistics[k]>=0);}
function beginReplay21(replaying){delete S.replay21;if(replaying){S.replay21={};for(const k of replayFields21)S.replay21[k]=copyState(S[k]);}}
function finishReplay21(){if(!S?.replay21)return;const baseline=S.replay21;for(const k of replayFields21)S[k]=copyState(baseline[k]);delete S.replay21;S.hp=S.maxHp;S.lastEvent={title:'再探索を終了',text:'金貨・カード・レリック・最大HP・強化・依頼進行を出発前に戻しました。物語と仲間の約束は保持。'};}
function replayNotice21(){return S?.replay21?'<div class="event-receipt" role="status"><strong>再探索 · 練習モード</strong><span>この地域内で得た報酬や強化、使った金貨は拠点帰還時に出発前へ戻ります。物語と仲間の約束は地域クリア時に保存されます。</span></div>':'';}


function migrateReplay21(){if(!S||S.replay21||['hub','victory','endingchoice','crossroads'].includes(S.screen)||!S.campaign)return;const hidden=S.battle?.hidden||S.reward?.hidden||S.battle?.enemies[0]?.name==='忘却の竜'||S.reward?.bossName==='忘却の竜';const replay=hidden?S.campaign.hiddenDefeated:S.campaign.cleared.includes(S.act);const checkpoint=S.campaign.checkpoint;if(replay&&checkpoint){const r={};for(const k of replayFields21)r[k]=copyState(checkpoint[k]);if(validReplay21(r)){S.replay21=r;save();}}}

// Presentation-only story layer; no card, combat, reward or route rule changes.
const novel22=[
 {question:'妹は、なぜ城塞に手紙を残したのか。',arrival:['灰に埋もれた城門で、あなたは一通の手紙を拾った。宛名はない。それでも、折り目を見ただけで妹のものだと分かる。','妹の手紙「迎えに来て。でも、鐘が三度鳴る前に、王様の話を聞いて」','昨日まで帰り道さえ知らなかった。今は、会って確かめたいことがある。あなたは灯の消えた城へ足を踏み入れた。'],discovery:['礼拝堂の壁には、妹の背丈と同じ高さに小さな傷が並んでいた。日付ではない。城の子どもたちと交わした、背比べの印だ。','鐘守の記録「王は最後まで民を逃がした。扉を閉めたのは、鍵を持つ少女だった」','妹は連れ去られただけではない。ここで誰かを助け、何かを選んだ。その理由を知る者が玉座にいる。'],before:['骸骨王「その手紙を持つ者よ。あの子を、ただ救われるだけの娘だと思うな」','王は錆びた剣を立てた。「森にいる魔女が、封印を解く言葉を知っている。だが道を教える前に、お前の灯が深淵に呑まれぬか見届ける」','あなた「妹が何を選んだとしても、まず本人の言葉を聞く。それまで、帰るのを諦めさせはしない」'],clear:['骸骨王は剣を下ろし、森へ通じる門を開いた。骨の指が、手紙の裏を指す。','消えかけていた文字が灯に浮かぶ。「私は、みんなを逃がすために扉を閉めた。けれど、もう一人では開けられない」','救出は、妹の選択を取り消すことなのか。それとも、その続きを共に選ぶことなのか。答えを求め、あなたは記憶を喰らう森へ向かう。']},
 {question:'封印は妹の命を守っているのか、奪っているのか。',arrival:['森には、名前のない墓が続いていた。木々を抜けるたび、あなたは妹との些細な記憶を一つ思い出す。いつも先に謝ったのは、どちらだっただろう。','枝に結ばれた紙片には、妹の筆跡で「忘れる前に、書いておく」とある。','森の奥で女の声がした。「思い出を頼りに歩くなら、なくした時に迷う。手紙を頼りにおいで」'],discovery:['魔女の小屋には、封印の設計図が残っていた。鍵の欄にあるのは、妹の名ではなく「帰りたいと願う者」という言葉だった。','魔女の覚え書き「少女の命は扉の向こうに保たれている。扉を砕けば、命ごと深淵に流れる。救うには、支えるものを変えねばならない」','妹だけを引き抜くことと、扉を閉じることは同じではない。封印が妹を閉じ込め、同時に守っている。'],before:['禁忌の魔女「私があの子に術を教えた。助かる方法だけを教えたつもりだった。でも、残る痛みまでは引き受けなかった」','魔女「君主は鍵を欲している。お前も、妹の代わりに誰かを残せばいいと考えるようになるのか」','あなた「まだ答えはない。だから、ここで終わらせない」魔女は本を閉じ、失敗した術をもう一度広げた。'],clear:['魔女は封印を書き換える言葉を手紙に重ねた。「玉座で選ぶのはお前だ。誰を救い、何を残すか」','その夜、夢の中で妹が言った。「私が残ったのは、誰かに褒めてほしかったからじゃない。ただ、目の前に人がいたから」','あなたは返事を書き始める。まだ届かなくても、今度は自分も言葉を残す。次の宛先は、深淵の君主の玉座だ。']},
 {question:'妹を取り戻すために、誰かを鍵に残さなければならないのか。',arrival:['最後の灯火と呼ばれる街には、朝を待つ人々がいた。あなたが城や森で聞いた名が、避難者の名簿にいくつも見つかる。','妹が守ったものは、世界という遠い言葉だけではなかった。ここで眠り、食事をし、誰かを待つ人々だった。','玉座への階段で、手紙が熱を持つ。向こう側に、妹がいる。'],discovery:['扉の内側から、妹の声が届いた。「今、鍵が抜けたら、この街まで流れ込む。だから私は、帰れないって言った」','あなた「帰りたくない、とは書いていなかった」','沈黙のあと、小さな返事があった。「うん。帰りたい。でも、私だけが帰る方法じゃ、嫌なんだ」'],before:['深淵の君主「鍵のない封印などない。少女を救うなら、お前が残れ。世界を救うなら、少女を残せ。あるいは、私のように力を選べ」','それは誘惑であり、この世界が繰り返してきた答えでもあった。','あなたは手紙をしまった。ここまで誰を助け、何を知り、何を求めたか。その旅のすべてを携えて、君主の前へ進む。'],clear:['玉座から闇が退いた。妹の声は、今はっきりと聞こえる。本編の結末で、あなたは封印と妹の運命を選ぶことができる。','だが玉座の背に、誰も触れていない星図があった。「この扉を作った者は、空の外から来た」','今日の選択がどんな結末を迎えても、誰かを鍵に残す仕組み自体はまだ消えていない。星骸の天文台には、その始まりが眠っている。']},
 {question:'誰が、犠牲を必要とする封印を作ったのか。',arrival:['天文台は、玉座よりも古かった。観測窓には、星ではなく、いくつもの別れの場面が映っている。','声は妹にも、あなた自身にも聞こえた。「ここで終わったことにすれば、先を知らずに済む」','あなたは窓に背を向ける。終わりの向こうに何があるかを、確かめに来たのだ。'],discovery:['星図の裏には、封印が作られた日の記録があった。最初の鍵もまた、大切な人の帰還を願った旅人だった。','その願いを力に変えた装置が、帰りたい者を次の鍵に選び続けた。君主は作り手ではなく、その装置に囚われた一人だった。','記録の最後には、灰燼の港へ運ばれた「原典」の名がある。仕組みを終わらせるには、その設計を読む必要がある。'],before:['星喰いの監視者「私は観測する。願いが鍵となり、鍵が次の願いを呼ぶ。その循環は、これまで一度も途切れていない」','あなた「記録にないなら、これから残す。誰か一人が戻れない結末だけを、繰り返したくはない」','観測窓が閉じ、星の光が槍となった。監視者を越えれば、港への航路が開く。'],clear:['監視者の記録から、港の提督が原典の最後の運搬先を知っていると分かった。彼もまた、帰りを待つ人を失っていた。','あなたは自分の返事を星図に挟む。「願いを燃料にするだけなら、いつまでも帰れない。帰ったあとの暮らしまで、道をつなごう」','星図が海図へ変わる。灰に覆われた海の向こうで、灯台が一度だけ光った。']},
 {question:'帰り道を守ることと、誰も帰さないことはどう違うのか。',arrival:['灰燼の港では、船がすべて陸に縛られていた。船主たちは出航を願うが、提督は灯台を閉ざしている。','岸壁の石には、帰らなかった者たちの名が刻まれていた。その隅に、妹の手紙と同じ印がある。','原典を積んだ船団は、北の山へ向かう途中で難破したという。提督だけが、最後の積荷が届けられた場所を知っていた。'],discovery:['沈没船の航海日誌に、妹がここへ来るはずだったことが記されていた。原典を探す道は、封印より前から存在していたのだ。','提督の追記「二度と誰も海で失いたくない。灯を消せば、船は出ない」','あなたは日誌を閉じる。失うことを恐れて閉じた扉も、外へ出られない者にとっては牢になる。'],before:['灰潮の提督「帰れと言われても、帰る家を失った者もいる。お前は、灯をつければすべて救えると思うのか」','あなた「思わない。それでも、出るか残るかは、その人が選べるようにしたい」','提督は錨を引きずった。「ならば、嵐の向こうまで道をつなげ。私を越えて、それを示せ」'],clear:['灯台に火が戻った。提督は北への海図を差し出す。「原典は氷の山を越えて、沈黙の書庫へ運ばれた」','帰還船の船室で、あなたは手紙の余白に書く。「会えた時、何を言えばいいか、まだ分からない。でも、君の話を最後まで聞きたい」','船は北へ向かう。救出のために始まった旅は、誰もが帰路を選べる世界を探す旅へと変わっていた。']},
 {question:'妹の決断を、誰が本当に知っているのか。',arrival:['白霜の山脈では、雪が音を吸い込んでいた。風の止むたび、妹の声が近くなる。夢なのか、封印に残る記憶なのかは分からない。','声「私が何を考えていたか、誰も聞かなかった。勇敢だったとか、仕方なかったとか、みんな先に答えを決めた」','あなた「今度は、君の返事を待つ」山頂への道に、小さな足跡が浮かんだ。'],discovery:['氷の道しるべの中に、妹が封印の前夜に書いた手紙が残っていた。届いた手紙とは、違う一通だ。','妹の届かなかった手紙「怖い。残りたくない。けれど、今は私にしか扉を閉められない。迎えに来てと言ってもいいのかな」','助けを求める言葉と、人を守る決断は、同時にあった。あなたはどちらも消さないよう、丁寧に紙を畳んだ。'],before:['霜冠の守護者「私は、少女が弱さを残した場所を守る。後世の者が都合のよい英雄に作り替えぬように」','あなた「怖かったという言葉ごと、連れていく。それを知ったうえで、先へ進みたい」','守護者の冠が凍りつく。氷を砕くことは、記憶を否定することではない。その奥へ進むための戦いだった。'],clear:['氷冠がほどけ、書庫への通路が開いた。守護者は、届かなかった手紙を持つあなたを止めなかった。','あなたの返事には、初めて迷いなく一文が書けた。「迎えに来てと言ってくれて、よかった」','その返事が届く場所を探して、あなたは山の向こうへ歩く。原典はもう、遠くない。']},
 {question:'犠牲以外で封印を支える方法は、本当にあるのか。',arrival:['沈黙の書庫には、帰れなかった者たちの手紙が収められていた。棚の一つには、あなたの筆跡の返事まで並んでいる。','司書の声「書かれなかった言葉も、ここでは記録になる。読むだけなら、傷つかずに済む」','あなたは返事を棚へ戻さなかった。届けるために書いた言葉を、ここで記録に変えるつもりはなかった。'],discovery:['原典には、途中で消されたもう一つの設計があった。鍵を一人の命に結ぶ代わりに、外の世界へ帰る道をいくつもつなぐ仕組みだ。','最初の作り手は失敗を恐れ、一人に負担を集める方法を選んだ。その未完成の代案を、司書は人の目に触れぬ場所へ隠していた。','城、森、街、天文台、港、山。あなたがつないできた道は、その代案の土台になる。最後の楔は、黎明の裂け目にある。'],before:['記憶喰いの司書「未完成の方法へ人々を導けば、すべてを失うかもしれない。確かな犠牲と、不確かな希望。お前は後者を選べるのか」','あなた「確かだと言って、妹一人に決めさせたのは誰だ。今度は、危うさも分け合う」','司書は頁を舞い上げた。過去を保存するだけの場所から、未来へ持ち出す一頁を選ぶために、あなたは本を開く。'],clear:['司書は消した頁を返した。「この先は、私にも書けない」','原典にあなたの返事を重ねると、文字が扉になった。妹の声が届く。「今度は、一緒に選べる？」','あなた「うん。もう答えを決めて迎えには行かない」二人の言葉が、黎明の裂け目へ続く道を照らした。']},
 {question:'誰かを残す物語を、ここで終わらせられるか。',arrival:['裂け目の向こうには、夜明けを待つ人々の影があった。旅で守った灯が、一つずつ暗闇の縁に並ぶ。','原典に重ねた便りから、妹の声がすぐ隣のように届く。姿が見えなくても、今は返事を交わせる。あなたは手紙を握りしめなくても歩けた。','声「怖いのは、まだ変わらない」あなた「自分もだよ。それでも、ここまで来た」'],discovery:['最後の楔に刻まれていたのは、王の名ではなく「別れを受け入れた者」という役目だった。誰かが諦めるたび、仕組みは正しいものとして保たれてきた。','原典は二つの道を示している。楔を砕いて皆で帰る道と、誰でも通れる境界として灯を残す道。どちらにも、一人を鍵に縛る必要はない。','あとは、道を閉じる王を越えるだけだ。あなたは、ようやく書き終えた返事を開いた。'],before:['黎明を阻む王「私がいなくなれば、帰る場所さえ変わる。失った者が戻ると、約束できるのか」','あなた「約束できるのは、もう一人で選ばせないことだけだ。帰ってからのことも、一緒に考える」','妹の声「それでいい」旅の最初に交わせなかった会話が、ここでようやく終わる。最後の戦いが始まった。'],clear:['王の影が消え、楔の向こうに朝が見えた。返事を読み終えた妹の声が、小さく笑う。「遅かったね。でも、来てくれてよかった」','ここまで誰を救い、何を残すかを選んできた。最後は、帰り道をどんな形で未来へ渡すかを選ぶ。','拠点で「遠征編の結末」を選べます。楔を砕いて皆と帰るか、自由な帰路を照らす灯を残すか。どちらの道にも、あなたが届けた返事が残る。']}
];
// Revisions: the three bells, the unanswered letter, and each guardian's motive pay off across chapters.
novel22[0].discovery[0]='城に一度目の鐘が響いた。礼拝堂の壁には、妹の背丈と同じ高さに小さな傷が並ぶ。子どもたちが逃げる前に残した、背比べの印だった。';
novel22[0].before[0]='二度目の鐘が鳴る。骸骨王「三度目で、少女の声は城から切り離される。私を倒すだけなら急げ。だが、あの子が何を選んだか聞くなら、今ここで足を止めよ」';
novel22[0].clear[0]='骸骨王は剣を下ろし、鳴り始めた三度目の鐘を、自らの刃で止めた。「私に残された役目は、これだけだ」。森への門が開き、骨の指が手紙の裏を指す。';
novel22[1].before[2]='あなた「妹の代わりを探しに来たんじゃない。妹が帰りたいと言えた理由を、なくしたくない」魔女は目を伏せた。「なら、私の間違いも持って行って」。失敗した術が二人の間に広がる。';
novel22[3].discovery[2]='原典は、封印を作った者の設計書だ。監視者はそれを灰燼の港へ移した。鍵を一人に戻す規則を、疑う者が読めないように。仕組みを終わらせる道は、その本からしか始まらない。';
novel22[4].arrival[2]='提督は、原典を北へ運ぶ船団をかつて護衛していた。難破を生き延び、最後の積荷を山の麓へ届けたあと、港へ戻って出航を禁じた。妹の足跡を追うには、彼が閉ざした航路を開かなければならない。';
novel22[4].discovery[0]='船倉から回収した航海日誌には、妹が魔女に原典の行方を尋ねていた記録があった。少女は旅立つ前に封印の崩壊を知り、別の道を探していた。だが城の避難が間に合わず、自ら扉を閉めたのだ。';
novel22[5].discovery[0]='氷の道しるべの中に、原典へ辿り着こうとした妹が巡礼者に託した手紙が残っていた。使者は吹雪に阻まれ、手紙は帰らなかった。あなたに届いた救出の手紙よりも前の、最後まで送れなかった本音だった。';
novel22[6].discovery[2]='設計には代償も書かれていた。道を一つに固定すれば安全だが、境界を見守る人々が必要になる。楔を砕けば誰も縛られないが、帰る世界は変わる。最後の楔は黎明の裂け目にある。選ぶ前に、この危うさを妹と分け合わなければならない。';
novel22[7].discovery[1]='原典は二つの道を示す。楔を砕けば、世界の形が変わっても誰も鍵に残らない。門に灯を据えれば、帰路は保たれる代わりに皆で境界を見守り続ける。どちらも、妹一人に答えを背負わせる道ではない。';
novel22[7].before[0]='黎明を阻む王「私は最初の鍵だった。帰れなかった者のために、帰る場所だけは変えてはならぬと願った。その願いが、次の鍵を求める王になった。お前は、私の別れまで無意味にするのか」';
novel22[7].before[2]='妹の声「あなたが残ったことを、間違いだったとは言わない。でも、次の誰かが残らなくてもいい明日を、私たちは選びたい」。王は初めて返事を失った。あなたは手紙を胸にしまい、最後の楔へ進む。';

// Editorial closure: keep the initial ending and later character positions consistent.
function bridgeLine35(a,stage,page){if(a!==3||stage!=='arrival'||page!==1)return '';return ({dawn:'妹は宿営地から、星図に重ねる便りを送ってくる。目の前の声は、観測窓が拾った記憶だった。あなたは窓の声と、今を生きる妹の言葉を混同しないよう、便りを開いた。',vigil:'境界に残した身体から、灯を介して道へ踏み出す。観測窓が映すのは、終わった別ればかりだった。外にいる妹と交わせる言葉は、まだ終わっていない。',sealed:'観測窓から、扉の向こうに残した妹と似た声が聞こえた。記録に映る声だけで、今の妹の答えを決めてはいけない。あなたは、まだ返事を書ける紙を開いた。',abyss:'王冠に従うはずの窓が、あなた自身の別れを映した。力を得ても、妹の返事まで命じることは出来ない。あなたは観測する声を遮り、聞き取れなかった言葉を探した。'})[S.story?.ending]||'';}
// Story revision 24: concrete memories and actions, four pages per scene.
const storyAdded24=[["手紙の端には、雨を避けるように何度も折り直した跡があった。急いで書いた言葉を、妹は捨てずにここへ残した。あなたは濡れた指を拭いてから、封を開いた。", "印の一つだけ、線が二本重なっている。背が伸びたと言い張る妹に、あなたが描き足した線と同じ癖だ。壁から手を離すと、鐘の余韻が指先に残った。", "王の剣先は震えていた。敵を待ち続けた腕ではない。閉じた門を、長いあいだ支えてきた腕だった。あなたは身構え直し、王が守っていた方角を見た。", "鳴らなかった三度目の鐘。その静けさを持って、あなたは森へ入る。手紙の裏に浮かんだ言葉が消えぬよう、火を小さく絞った。"], ["木の根に、妹が昔つけていた赤い糸が引っかかっていた。あなたは思わず名前を呼ぶ。返ってきたのは自分の声だけだった。糸を拾い、手紙と一緒にしまう。", "設計図の隅は、何度も消した跡で薄くなっていた。魔女も、別の方法を探していた。見つけられなかった時間だけが、紙の傷になって残っている。", "魔女は灯をあなたの背後へ移した。退路を塞ぐためではない。「失敗したら、そちらへ逃げなさい」。そう言ってから、誰にも聞こえぬほど小さく少女の名を呼んだ。", "返事の最初には「どうして」と書いて、消した。その下へ「手紙を読んだ」と書く。責めたい気持ちが消えたわけではない。ただ、先に伝えたいことがあった。"], ["名簿の端で、一人の子どもが眠っていた。手には木彫りの鳥がある。城で見た背比べの印を思い出し、あなたは毛布をかけ直した。", "扉に手を当てると、向こうから二度、叩く音がした。子どもの頃、暗い部屋で互いの居場所を知らせた合図だった。あなたも二度、叩き返した。", "君主は答えを急がせた。だがあなたは、扉から手を離す前にもう一度だけ声をかけた。「まだ、ここにいる」。今度の返事は、すぐに聞こえた。", "星図の端に、港と山と書庫を結ぶ線がある。妹の運命を選ぶことと、この仕組みを終わらせることは別の問いだった。あなたは、その線を指でたどった。"], ["窓に映る別れの一つに、あなたの知らない若い王がいた。王冠を持たず、誰かの帰りを待っている。背中の輪郭だけが、遠い玉座の影と似ていた。", "原典を運び出した荷札には、監視者の印と司書の署名が重なっていた。知らなかったのではない。知ったうえで隠した者がいる。", "監視者の槍が止まる。「前にも、同じことを言った者がいた」。あなたは顔を上げた。「その人の失敗も、持って行く」。星の光が、もう一度震えた。", "海図には、灯台の火が消えた年が小さく記されていた。難破の日と同じ年だった。港へ急ぐ理由が、一つ増えた。"], ["船具屋の女は、毎朝同じ綱を解こうとしていた。出航を諦めた夫のかわりだという。「乗るかどうかは、船が動いてから決める」。そう言って結び目へ爪を立てた。", "日誌には、助かった船員の名もあった。失った者の名ばかりを刻んだ岸壁には、その名がない。あなたは生存者の頁を開いたまま、提督のもとへ向かった。", "提督は錨を持ち上げ、船員たちを見ないまま言った。「私が止めたのだと、皆が恨んでくれる方がよかった」。あなたは答えず、背後の綱が解かれる音を聞いた。", "岸壁で、船具屋の女が最後の綱を解いた。提督は船に乗らず、灯台へ階段を上がっていく。見送ることから始める者もいる。船は、その火を背に進んだ。"], ["足跡は途中で消えた。妹がここを歩いた証拠ではない。封印に触れた雪が、誰かの記憶をかたどっているのだ。それでも、あなたは踏み荒らさずに脇を歩いた。", "手紙の末尾に、何かを書こうとしてやめた短い線がある。あなたは続きを想像し、やめた。書かれなかった言葉まで、代わりに決めたくはなかった。", "守護者の胸には、配達鞄の留め金が凍りついていた。「届かなかった言葉を、今度こそ届けるのか」。あなたは手紙を上着の内側へ入れ、うなずいた。", "吹雪が途切れた。手紙を託された巡礼者は、帰れなかった。それでも、届けようとした言葉は残った。あなたは道しるべに火を一つ置き、振り返らずに降りていく。"], ["棚の手紙を一通だけ開く。「着いたら、窓を二度叩いて」。返事は同じ箱になかった。あなたは封筒を元の向きに戻し、自分の返事を確かめた。", "代案の余白には、海図と山道の目印に似た図がある。人の願いを燃やす代わりに、人が往来する道を支えにする。消された設計は、一人で完成させるものではなかった。", "司書は一枚の頁を握り締めた。「最初の王に、出来ないと告げたのは私だ」。その指がほどけるまで、あなたは攻撃せずに待った。", "あなたは原典の空白を残した。まだ帰っていない人の言葉を書くために。司書はその頁を見つめ、初めて本を閉じずに見送った。"], ["闇の縁に、城の子どもが持っていた木彫りの鳥が置かれていた。誰かが運んだ小さな目印だった。あなたはそれを拾わず、その横へ灯を置いた。", "妹はしばらく黙っていた。「帰ったら、知らない町になっているかもしれないね」。あなたも黙り、それから答えた。「そうしたら、どこから歩こうか」", "王は玉座を振り返った。そこには、待ち人のための空いた椅子がある。「忘れろと言うのか」。妹の声が返した。「覚えたまま、扉を開けて」。", "扉に二度、音がした。あなたも二度、返す。もう居場所を確かめるためだけではなかった。ここから先へ進む合図だった。"]];
for(let a=0;a<8;a++)for(const [i,stage] of ["arrival","discovery","before","clear"].entries())novel22[a][stage].push(storyAdded24[a][i]);
novel22[2].clear[0]='玉座から闇が退いた。妹の声が、今はっきり聞こえる。けれど鍵は抜けず、封印の代わりになる支えも、まだ見つかっていない。あなたはすぐに答えを選ばず、手紙を開いた。';
novel22[5].before[0]='霜冠の守護者「私は、手紙を届けられなかった巡礼者だ。せめて、この言葉が凍りついたまま失われぬよう守ってきた。勇敢だった、の一言で少女の恐れを消す者には渡せぬ」';
novel22[6].discovery[1]='司書の書き込みがあった。「皆で支える方法は、まだ試せない」。彼は未完成の頁を隠し、一人を鍵にする設計だけを最初の王へ渡した。王が選んだ犠牲は、すべてを知らされたうえの決断ではなかった。';
function baseStoryLine24(a,stage,page){const bridge=bridgeLine35(a,stage,page);if(bridge)return bridge;if(a===3&&stage==='arrival'&&page===0){const end=S.story?.ending;return ({dawn:'妹を宿営地へ送り届けても、深淵の震えは止まらなかった。救出のために書き換えた封印の、根にある装置が動き続けている。あなたは星図を開き、妹と話した。「今度は帰るためだけじゃなく、もう奪わせないために行く」',vigil:'妹を外へ送り出したあと、鍵となったあなたの前に星図の道が浮かんだ。身体は境界に縛られていても、灯を介して道へ踏み出せる。妹の声が届く。「今度は私も、そちらへ届く言葉を探す」',sealed:'閉じた扉の向こうで、妹はまだ鍵を支えている。街を守るために選んだ静けさが、胸に重かった。封印は保たれている。だからこそ、今のうちに別の支えを探せる。あなたは残された星図を開いた。',abyss:'王冠を得ても、装置は新しい鍵を求め続けた。支配すれば終わると考えたあなたのもとへ、妹の呼び声が届く。命令するためではなく、聞くために。あなたは玉座を離れ、星図の先へ進んだ。'})[end]||novel22[a][stage][page];}return novel22[a][stage][page];}

const companionScenes25={
 '0:clear':{id:'noel',plain:'ノエルは鳴らなかった鐘を見上げた。「兄さんの時にも、止まってくれたらよかった」。あなたは返す言葉を探し、やめた。少年が歩き出すまで、隣で待った。',done:'ノエルは城門に刻んだ兄の名へ触れた。「助かった人の名前も、ここに残そう」。あなたは明かりを寄せた。少年は、妹が守った子どもたちの名を書き始めた。'},
 '1:clear':{id:'lyra',plain:'リラは返事を書き損じた紙を拾った。「傷の場所を知らないと、手当ても出来ないから」。読まずに畳み、あなたへ返す。その手には薬草の匂いがした。',done:'リラは故郷へ託した薬草の包みと同じ結び方で、手紙を留めた。「届くまで、効いたかどうか分からない。それでも送るの」。あなたはその結び目を覚えた。'},
 '2:before':{id:'garen',plain:'ガレンが扉の前で膝をついた。「命令だった、と言えば終わってしまう。少女をここへ通したのは私だ」。あなたは盾の縁を押し上げた。「本人に話してくれ。ここで終わりにしないで」',done:'ガレンは誓いを刻んだ盾を、扉へ向けた。「今度は、少女が出てくる方を守る」。鎧の震えは消えていない。それでも、その足は退かなかった。'},
 '3:clear':{id:'noel',plain:'ノエルは星図の余白へ、帰れた者の名を書いた。「観測するなら、こっちも数えてほしい」。見張り台に初めて、人の手で書いた文字が残った。',done:'ノエルは小さな鐘を一度だけ鳴らした。呼び戻すためでも、忘れないためでもない。「ここに道があるよ」。海図の先へ、澄んだ音が渡っていった。'},
 '4:clear':{id:'garen',plain:'ガレンが岸壁の綱を巻いていた。提督は手伝おうとして、やめた。「許されるために働くのか」。ガレンは首を振る。「明日、誰かがここを通るからだ」',done:'ガレンは提督へ、守れなかった者の名を告げた。提督も一人の名を返す。それ以上は話さず、二人で次の船の綱を巻いた。'},
 '5:clear':{id:'lyra',plain:'リラは巡礼者の灯に布を巻き、風を避けた。「届かなかったことと、無駄だったことは違う」。あなたは返事の封を押さえた。雪の上で、小さな火が揺れ続けた。',done:'リラのもとへ故郷から短い返事が届いた。薬草が間に合った、とだけある。彼女は笑ってから、少し泣いた。「あなたの返事も、早く届けよう」。荷物を結び直す音がした。'},
 '6:before':{id:'noel',plain:'ノエルは手紙の棚に、兄の名を見つけられなかった。「書けなかった人は、いなかったことになるの？」。司書の手が止まった。あなたは原典の空白を指で開いた。',done:'ノエルは兄の名を書いた紙を、閉じかけた本の間に挟んだ。「記録を消したら、守れたことになるの？」。司書は答えず、隠していた頁を机へ置いた。'},
 '7:clear':{id:'garen',plain:'ガレンが開いた門の脇へ盾を立てた。妹の声を聞いても、すぐには顔を上げない。「話したいことがある」。返事は短かった。「うん。帰りながら、聞かせて」',done:'ガレンは門を支えたあと、盾を自分の腕へ戻した。もう誰かを閉じ込めるための門ではない。妹がその横を通る時、彼は初めて、見送る礼をした。'}
};
function companionReflection25(a,stage){const r=companionScenes25[`${a}:${stage}`];if(!r||!S.allies?.includes(r.id))return '';return S.quests?.includes(r.id)?r.done:r.plain;}
function storyLine24(a,stage,page){const base=baseStoryLine24(a,stage,page),line=page===3?companionReflection25(a,stage):'';const voice=page===3?classVoices29[`${a}:${stage}`]?.[S?.cls]:'';let text=base+(line?'\n\n'+line:'')+(voice?'\n\n'+voice:'');if(S?.cls==='mage')text=text.replace('あなたは剣先を楔へ向けた','あなたは杖先を楔へ向けた');else if(S?.cls==='occult')text=text.replace('あなたは剣先を楔へ向けた','あなたは呪具を楔へ向けた');else if(S?.cls==='rogue')text=text.replace('あなたは剣先を楔へ向けた','あなたは短剣の先を楔へ向けた');return text;}
function journalScene25(a,stage){let last='';return novel22[a][stage].map((_,page)=>{const art=storyIllustration23(a,stage,page),changed=art!==last;last=art;return (changed?art:'')+`<p>${esc(storyLine24(a,stage,page))}</p>`;}).join('');}


// Editorial revision 26 and optional letters, unlocked by read scenes only.
novel22[0]["arrival"][3]="手紙の端には、雨を避けるように何度も折り直した跡がある。あなたは読み終えた紙を、同じ折り目で丁寧に畳んだ。返事を届けるまで、失くさないよう胸の内側へしまう。";
novel22[0]["before"][3]="王は剣を構えたが、その切っ先は玉座ではなく門へ向いていた。「城の闇を連れて森へ行かせるわけにはいかぬ」。あなたの足元から伸びる影を、王の刃が照らし出す。";
novel22[1]["before"][3]="魔女は灯をあなたの背後へ移した。「私の術が、お前の記憶まで喰おうとしている。逃げるなら、明かりの方へ」。本を閉じようとする手を黒い蔓が縛る。あなたは、その手へ向かって剣を構えた。";
novel22[2]["before"][1]="君主は扉に指をかけた。「この街を失う覚悟もない者が、鍵を外すと言うのか」。扉の向こうで、妹が二度叩く。あなたは君主ではなく、その音の方を見た。";
novel22[3]["before"][3]="監視者の槍が止まる。「前にも、同じことを言った者がいた。帰れなかった」。あなたは星図を畳んだ。「その人がどこで迷ったか、記録は残っているか」。監視者は答えず、最後の観測窓を閉じた。";
novel22[4]["before"][3]="提督は錨を持ち上げた。「皆は明日も出航を願う。私は、そのたびにまた誰かを失う」。あなたは背後の船へ目をやった。「危険を知らせる火に戻してくれ。出られなくする火ではなく」。鎖が海面を打った。";
novel22[6]["before"][3]="司書は一枚の頁を握り締めた。「最初の王に、出来ないと告げたのは私だ」。渡しかけた手が止まり、棚の鎖が本を引き戻す。あなたは頁を裂かぬよう、鎖の留め金へ刃を向けた。";
novel22[7]["clear"][2]="妹は原典の二つの道へ指を重ねた。「どちらへ行っても、帰ってからのことを話そう」。楔を砕くための刃と、門を照らすための灯が並ぶ。あなたは、もう一度その違いを確かめた。";
const letters26=[["折り目", "あなたの返事", "王様が止めた鐘のことを、忘れないでおく。君が残した手紙の折り目を、何度も指でなぞった。迎えに行く。けれど今度会ったら、まず話を聞く。"], ["消した言葉", "あなたの返事", "魔女に会った。怒っているのかと聞かれて、うまく答えられなかった。君のことも、自分のことも、まだ分からないことが多い。分からないままでも、歩いていく。"], ["二度の合図", "扉越しの言葉", "声が聞こえなくなっても、二度叩いて。私も二度返す。何を選ぶにしても、私がここにいることを忘れないで。迎えに来てくれて、ありがとう。"], ["記録の外へ", "あなたの返事", "天文台の窓には、終わった別ればかりが映っていた。帰った人たちの朝食や、その次の日の喧嘩は、どこにもなかった。そういう日を、ここから先に残したい。"], ["灯台の火", "あなたの返事", "船が出た。岸に残った人もいた。提督は最後まで、手を振らなかった。それでも船の窓から振り返ると、灯台の火がずっと見えていた。"], ["書かなかった続き", "あなたの返事", "怖かったんだね。知るのが遅くなった。君が書きかけてやめた言葉を、自分の都合で埋めないようにする。会った時、話しても、話さなくてもいい。"], ["空白の頁", "灯に届いた言葉", "帰ったらどうする、と聞かれても、まだ分からない。でも、分からないことを一緒に考えてくれるなら帰りたい。原典の空白は、そのために少し残しておいて。"], ["帰路", "最後の返事", "窓を二度叩く音を、遠くの誰かの合図だと思っていた。今は、帰ってきた人を迎える音にも聞こえる。手紙をしまう。ここから先は、顔を見て話そう。"]];
function letterJournal26(){const seen=ensureNovel22().seen;return `<section class="panel letter-journal26"><h2>旅の往復書簡</h2><p class="small muted">歩いてきた道で残した返事と、灯に届いた言葉。</p>${letters26.map(([title,from,body],a)=>seen.includes(`${a}:clear`)?`<details><summary>第${a+1}章 · ${title}</summary><article class="letter-paper26"><p class="eyebrow">${from}</p><p>${esc(body)}</p></article></details>`:`<p class="small muted">第${a+1}章の余白 · その章の攻略後の場面を読むと解放</p>`).join('')}${endingLetter27()}</section>`;}


// Final chapter: the king's grief and the mechanism's last resistance.
novel22[7].arrival[3]='闇の縁に、避難した子どもの木彫りの鳥が置かれていた。誰かが運んだ、小さな道しるべだ。奥には二つの椅子がある。王は一方の埃だけを、毎日拭いていた。';
novel22[7].discovery[0]='最後の楔には「別れを受け入れた者」と刻まれていた。王が最初の鍵になった時の役目だ。だが装置はその別れを終わらせず、帰りたい者を次の支えへ結び続けた。待ち人の椅子だけが、空いたまま残った。';
novel22[7].before[1]='あなた「あなたの待つ人を、連れて帰るとは約束できない」。王の指が、椅子に掛かった古い布を握った。「では、何を開けに来た」。あなたは妹の声がする方へ灯を寄せた。「今、帰りたいと言っている人の道を」';
novel22[7].before[3]='王は楔から手を離そうとした。だが黒い鎖が腕を引き戻し、門が閉じ始める。「私が願う限り、止まらぬのか」。あなたは剣先を楔へ向けた。妹が言う。「忘れなくていい。手を離して」。最後の戦いは、その鎖を断つために始まった。';
novel22[7].clear[0]='楔を縛る鎖が切れた。王の指から古い布がほどけ、空いた椅子へ静かに落ちる。「待っていたことだけは、覚えていてくれ」。影が消えたあと、妹の声が言った。「うん。覚えている」';
function epilogueAfter27(id){
 const core=id==='dawn'?['帰り道の地形は変わっていた。昨日の橋はなく、川の向こうに新しい浅瀬がある。妹は原典を閉じた。「もう、これに書いてある通りじゃないんだね」。あなたは足元の石を確かめ、一歩ずつ渡り始めた。','たどり着いた家の窓を、妹が二度叩いた。返事はない。二人で少し笑ってから、鍵を探した。遠くで鐘が鳴る。今度は、何かが閉じるまでの数を数えなくてよかった。']:['境界を見守る最初の当番表には、帰還した人たちが自分で名を書いた。来月は休みたいという者がいて、隣の者が引き受ける。灯を保つ役目は、ここから去る自由まで奪うものではなかった。','妹は門の傍らへ、新しい紙を結んだ。「次の見回りへ。油は階段の下にあります」。帰宅すると、窓を叩く二度の音がした。今夜の当番を終えた旅人が、灯の無事を知らせに来ていた。'];
 const voices=[];
 if(S.allies?.includes('noel'))voices.push(S.quests?.includes('noel')?'ノエルは兄の名を書いた小さな板を持ち帰った。窓辺に置き、その隣へ、これから覚える人たちのための空白を残した。':'ノエルは小さな鐘を荷物から出した。「城へ戻ったら、話したいことがある」。旅が終わっても、置いてきた言葉を拾う道は残っている。');
 if(S.allies?.includes('lyra'))voices.push(S.quests?.includes('lyra')?'リラの故郷から、乾燥した薬草の束が届いた。包みには「次は、こちらから」とある。彼女はほどいた紐を捨てず、新しい包みを作り始めた。':'リラは残った薬草を数え、故郷へ送る便りを書いた。救えたものだけを話す手紙にはしなかった。書き終えるまで、あなたと妹は黙って待った。');
 if(S.allies?.includes('garen'))voices.push(S.quests?.includes('garen')?'ガレンは盾を門へ置き去りにしなかった。「次に守る人は、自分で選ぶ」。妹はうなずき、その腕に新しい旅の荷物を一つ預けた。':'ガレンは妹と長く話した。声は小さく、あなたは席を外した。帰ってきた時、二人はまだ黙っていた。それでも、同じ卓に着いていた。');
 return `<section class="epilogue-after27"><h3>帰ったあとのこと</h3>${core.map(x=>`<p>${esc(x)}</p>`).join('')}${voices.length?`<details><summary>仲間たちのその後</summary>${voices.map(x=>`<p>${esc(x)}</p>`).join('')}</details>`:''}</section>`;
}
function endingLetter27(){const id=ensureCampaign().epilogue20;if(!id)return '';return `<details><summary>帰路の、その先へ</summary><article class="letter-paper26"><p class="eyebrow">妹からの手紙</p><p>${id==='dawn'?'窓の音が聞こえたら、すぐ開けなくてもいいよ。眠っていたら、起きてからで。返事が遅いことと、返事がないことは違うって、今なら思える。今日は川の向こうまで行ってくる。帰ったら、見つけた道を話すね。':'今日の見回りは私じゃないから、少し遠くまで歩いてくる。灯のことは、次の人に伝えておいた。帰り道があると思うと、知らない場所へ行ってみたくなるね。夕飯までには帰ります。'}</p></article></details>`;}


const companionStories28={
 noel:{intro:['ノエル「鐘を鳴らす係だった。逃げろって知らせるのが、自分の仕事だったんだ」','少年は舌をかみ、手の中の鐘を伏せた。「妹さんは、戻ってきた人まで数えてた。あの人を探すなら、見つけた人を置いていかないでほしい」','あなたは抜け道の暗がりを見た。「全部助けられるとは言えない。それでも、見なかったことにはしない」。ノエルは初めて、顔を上げた。'],quest:['ノエル「兄さんの名前を彫ったら、もう帰ってこないって認めるみたいで。ずっと、ここまで来られなかった」','崩れた石をどかせば、城門の銘板に手が届く。あなたは手袋を締め直した。少年は鐘を差し出し、すぐに引っ込める。「鳴らすのは、自分でやる」','あなた「名前は、どの字を書く？」。ノエルは指で埃の上へ一文字ずつ書いた。あなたは、それが消える前に石の位置を確かめた。'],yes:'ノエルは最後の一文字をなぞり、小さな鐘を鳴らした。音が消えるまで、二人とも動かなかった。',later:'ノエルは鐘をしまった。「今は、まだ声に出来ない」。あなたは急がせず、城門の場所を地図へ残した。'},
 lyra:{intro:['リラ「薬草を取りに戻ったら、道が変わっていた。森はそうやって、帰る理由から先に食べるの」','彼女は薬袋を閉じた。「妹さんのためなら手伝う。でも、途中の人に使う薬を惜しめと言うなら、別の道を行く」','あなた「助けたい人がいるのは、君も同じなんだね」。リラはうなずき、二人分の水を火へかけた。'],quest:['リラ「故郷には、私が戻ると思って待っている人がいる。薬だけでも届けば、何日かは持つ」','包みを預かる使者は、危険な山道を越える運賃を求めていた。あなたの手元にも、これから必要になる金貨がある。リラは袋へ手を伸ばさず、返事を待った。','あなた「何を渡したか、分かるように書こう」。リラは薬草の量と煎じ方を書き、最後の一行で筆を止める。「元気です、でいいかな」。あなたはうなずいた。'],yes:'使者が去ったあと、リラは残りの薬草を数え直した。「間に合うといい」。祈るだけで終わらせず、次の薬を作るために火を起こした。',later:'リラは包みの口を、きつく結びすぎないよう留め直した。「次に使者に会えたら、また話してもいい？」。あなたは、その包みが潰れぬよう荷物を空けた。'},
 garen:{intro:['ガレン「少女を扉まで案内したのは私だ。守る役目だと、言い聞かせていた」','黒い兜を脱ぐ。戦傷よりも、眠っていない目が先に見えた。「許してほしいと言う資格はない。ただ、もう一度命令を待つだけには戻りたくない」','あなた「許すかどうかを決めるのは、妹だ。ここから何をするかは、あなたが決めてくれ」。ガレンは、伏せた盾を拾い上げた。'],quest:['ガレン「名を読まなかった。数で報告すれば、顔を思い出さずに済むからだ」','観測室の扉は崩れかけている。刻まれた名を読むあいだ、二人で石を支えなければならない。ガレンは盾を差し込み、あなたへ無理はするなと言いかけて、やめた。','あなた「最初の人から、読もう」。彼は一人目の名を口にした。声が途切れるたび、あなたは扉を押し返し、続きを待った。'],yes:'最後の名を読み終えても、ガレンは盾を抜かなかった。石が止まる位置を確かめ、次の人が安全に通れるまで、二人で扉を支えた。',later:'ガレンは扉に目印を残した。「今は、まだ支えきれない」。あなたは次に使う楔の大きさを測った。戻るための準備を、二人で荷物へ加えた。'}
};
function companionPortrait28(id){const name=companions.find(c=>c.id===id)?.name||'';return `<figure class="story-figure story-wide24"><img src="${classArt29(`assets/companion-${id}28.webp`)}" alt="${esc(name)}との対話" loading="lazy" decoding="async"><figcaption>${esc(name)}</figcaption></figure>`;}
function companionTalk28(id,quest=false){return `<div class="companion-talk28">${companionStories28[id][quest?'quest':'intro'].map(x=>`<p>${esc(x)}</p>`).join('')}</div>`;}
function companionJournal28(){const entries=S.chronicle||[];return `<section class="panel"><h2>仲間との約束の記録</h2>${companions.map((c,i)=>{const met=S.allies?.includes(c.id)||entries.some(e=>e.event===14+i);if(!met)return '';const personal=entries.filter(e=>e.event===17+i),done=S.quests?.includes(c.id);return `<details><summary>${c.name} · ${S.allies?.includes(c.id)?'同行中':'別れた仲間'}</summary>${companionPortrait28(c.id)}${companionTalk28(c.id)}${S.allies?.includes(c.id)?'<p>同行の約束を交わした。</p>':'<p>物資を受け取り、それぞれの道を進んだ。</p>'}${personal.length||done?`<h3>${personalQuests[i].title}</h3>${companionTalk28(c.id,true)}<p>${esc(done?companionStories28[c.id].yes:companionStories28[c.id].later)}</p>`:'<p class="small muted">この仲間の個人依頼は、まだ記録されていません。</p>'}</details>`;}).join('')||'<p>旅の途中で仲間と出会うと、その言葉がここに残ります。</p>'}</section>`;}



const classVoices29={"0:arrival": {"warrior": "鎧の内側で、手紙の角が胸に触れた。これまで門を守るために立ってきた。今度は、閉じた門の向こうへ迎えに行く。", "rogue": "人目を避ける道なら、いくつも知っている。それでも手紙を残した妹は、見つけてほしいと願っていた。あなたは初めて、門の正面へ灯を向けた。", "mage": "封の痕跡を調べれば、使われた術は分かるかもしれない。だが先に、言葉として読みたかった。あなたは解読用の道具をしまい、手紙を胸へ戻した。", "occult": "手紙には、封印に触れた者の冷たさが残っていた。代償を払った印を、あなたは知っている。それを必要な犠牲だったと呼ぶ前に、本人の声を聞こうと思った。"}, "1:discovery": {"warrior": "設計図の輪を、あなたは城門の支柱に重ねて見た。一本を抜くなら、先に別の支えが要る。剣では決められないことを、魔女に尋ねた。", "rogue": "図の端に、消された細い道筋がある。侵入路を探す時と同じように、あなたは閉じた輪の外を見た。魔女はその指先を止めなかった。", "mage": "書き換えた跡が何層もある。一度で完成した術ではない。あなたが式の順番を追うと、魔女は隠していた下書きも机へ広げた。", "occult": "「支える命は、途中で替えられる」。余白の文字に、あなたは指を止めた。それは救出の手順でも、次の犠牲を作る手順でもある。魔女に、誰がこの一行を書いたのか尋ねた。"}, "7:before": {"warrior": "門を押し返す王の腕を見て、あなたは盾を低く構えた。倒すべき相手だけを見ていた頃には、その震えを見落としていただろう。", "rogue": "王の背後に、もう一つの影がある。楔から伸びる鎖の影だ。あなたは王の喉ではなく、その留め金へ狙いを移した。", "mage": "原典の式と、目の前の楔が重なった。壊す箇所を誤れば、帰路まで失う。あなたは妹の声を確かめ、最後にほどく順番を口にした。", "occult": "王の願いが、鎖へ流れ込んでいる。願いを消せばよいという術なら、あなたは使わなかった。覚えたまま手を離すための道を、妹の声と共に探した。"}};

const classArtVariants29={"assets/companion-lyra28.webp": {"warrior": "assets/companion-lyra28.webp", "rogue": "assets/lyra-rogue29.webp", "mage": "assets/lyra-mage29.webp", "occult": "assets/lyra-occult29.webp"}, "assets/story-atlas23.webp": {"warrior": "assets/story-atlas23.webp", "rogue": "assets/story-atlas-rogue29.webp", "mage": "assets/story-atlas-mage29.webp", "occult": "assets/story-atlas-occult29.webp"}, "assets/story-bell24.webp": {"warrior": "assets/story-bell24.webp", "rogue": "assets/bell-rogue30.webp", "mage": "assets/bell-mage30.webp", "occult": "assets/bell-occult30.webp"}, "assets/story-watch24.webp": {"warrior": "assets/story-watch24.webp", "rogue": "assets/watch-rogue30.webp", "mage": "assets/watch-mage30.webp", "occult": "assets/watch-occult30.webp"}, "assets/story-witch25.webp": {"warrior": "assets/story-witch25.webp", "rogue": "assets/witch-rogue30.webp", "mage": "assets/witch-mage30.webp", "occult": "assets/witch-occult30.webp"}, "assets/story-snow25.webp": {"warrior": "assets/story-snow25.webp", "rogue": "assets/snow-rogue30.webp", "mage": "assets/snow-mage30.webp", "occult": "assets/snow-occult30.webp"}, "assets/story-harbor26.webp": {"warrior": "assets/story-harbor26.webp", "rogue": "assets/harbor-rogue30.webp", "mage": "assets/harbor-mage30.webp", "occult": "assets/harbor-occult30.webp"}, "assets/story-library26.webp": {"warrior": "assets/story-library26.webp", "rogue": "assets/library-rogue30.webp", "mage": "assets/library-mage30.webp", "occult": "assets/library-occult30.webp"}, "assets/story-king27.webp": {"warrior": "assets/story-king27.webp", "rogue": "assets/king-rogue30.webp", "mage": "assets/king-mage30.webp", "occult": "assets/king-occult30.webp"}, "assets/companion-noel28.webp": {"warrior": "assets/companion-noel28.webp", "rogue": "assets/noel-rogue30.webp", "mage": "assets/noel-mage30.webp", "occult": "assets/noel-occult30.webp"}, "assets/companion-garen28.webp": {"warrior": "assets/companion-garen28.webp", "rogue": "assets/garen-rogue30.webp", "mage": "assets/garen-mage30.webp", "occult": "assets/garen-occult30.webp"}, "assets/dragon-warrior31.webp": {"warrior": "assets/dragon-warrior31.webp", "rogue": "assets/dragon-rogue31.webp", "mage": "assets/dragon-mage31.webp", "occult": "assets/dragon-occult31.webp"}, "assets/story-lastlight-arrival38.webp": {"warrior": "assets/story-lastlight-arrival38.webp", "rogue": "assets/story-lastlight-arrival38-rogue.webp", "mage": "assets/story-lastlight-arrival38-mage.webp", "occult": "assets/story-lastlight-arrival38-occult.webp"}, "assets/story-lastlight-before38.webp": {"warrior": "assets/story-lastlight-before38.webp", "rogue": "assets/story-lastlight-before38-rogue.webp", "mage": "assets/story-lastlight-before38-mage.webp", "occult": "assets/story-lastlight-before38-occult.webp"}, "assets/story-lastlight-clear38.webp": {"warrior": "assets/story-lastlight-clear38.webp", "rogue": "assets/story-lastlight-clear38-rogue.webp", "mage": "assets/story-lastlight-clear38-mage.webp", "occult": "assets/story-lastlight-clear38-occult.webp"}};
function classArt29(src){return classArtVariants29[src]?.[S?.cls]||src;}


// Optional dragon records use existing discovery and victory flags only.
const dragonRecords31=[
 {id:'arrival',title:'星の鎖に残る声',lines:['観測室の壁には、小さな窪みがいくつも並んでいた。どれにも、宛名のない手紙が一通ずつ入っている。竜は、その棚を翼の下へ隠すように眠っていた。','一通の裏に、城で見た背比べと似た印があった。帰れなかった人だけではない。帰った人が、帰れなかった誰かへ書いた手紙もある。','竜の声「閉じた扉を開けば、忘れたことまで戻ってくる。それでも、名を呼ぶのか」。真鍮の鎖が鳴る。竜が動かしたのではなかった。星の装置が、その翼を引き戻していた。','あなたは手紙へ触れず、灯を床へ置いた。読まれなかった言葉を守る竜と、竜を眠らせ続ける装置。その二つを、同じものとして壊すわけにはいかない。']},
 {id:'before',title:'忘れたままにはしない',lines:['果たしてきた仲間との約束を示すと、竜が片目を開いた。苦しい記憶に向き合い、誰かへ言葉を届けたこと。違う形の約束が、同じ扉へ届いていた。','竜の声「私は名前を預かった。だが装置は、痛みを消すためだと言って名を削った。返す場所をなくした言葉だけが、私の内に積もっていった」','あなた「君を倒せば、手紙はどうなる」。竜は答えようとして、歯を食いしばった。星の輪が回り、鎖が喉元まで締まる。侵入者を排せという命令が、竜の声を覆った。','竜の声「忘れないと言うなら、私が噛み砕いてしまう前に、この命令を断て」。あなたは武器を構える。棚の手紙に火が移らぬ位置を確かめてから、竜へ向き直った。']},
 {id:'clear',title:'名前を返す空',lines:['星の輪が止まり、竜の翼から鎖が外れた。棚は崩れなかった。あなたが床へ置いた灯のそばに、古い手紙が一通だけ滑り落ちる。','宛先を消された封筒に、竜は爪の先で小さな星を描いた。「名前を思い出すまで、これを目印にしよう」。消えた文字を、あなたが勝手に書き直すことはしなかった。','竜の声「少女の声を、ここへ預けようとした者がいた。だが、あの子は自分で手紙を残した。お前がここまで届いたのは、私が道を示したからではない」','あなたは星の護符を握り、空いた窓を見上げた。忘れないことと、同じ場所へ縛り続けることは違う。竜は棚を守る役目を選び直し、今度は自分の意思で翼を畳んだ。']}
];
function dragonStageOpen31(id){const c=ensureCampaign();return c.hiddenDiscovered&&(id==='arrival'||id==='before'&&(S.quests?.length||0)>=2||id==='clear'&&c.hiddenDefeated);}
function dragonArt31(){return `<figure class="story-figure story-wide24"><img src="${classArt29('assets/dragon-warrior31.webp')}" alt="忘却の竜と${classes[S.cls].name}" loading="lazy" decoding="async"><figcaption>忘却の竜 · 返せなかった名前の保管庫</figcaption></figure>`;}
function dragonCompanion31(){const voices={noel:'ノエルは鐘を鳴らさず、竜へ兄の名を告げた。「覚える人が増えたら、少しは軽くなるかな」。竜はうなずき、一つの棚を灯の方へ向けた。',lyra:'リラは薬草の包みを持ち直した。「届ける相手がいるなら、まだ送れる」。竜は手紙を一通選び、薄い羽の欠片で包んだ。長い眠りのあとに、初めて荷造りをした。',garen:'ガレンは盾を下ろし、宛名の消えた封筒へ頭を垂れた。「覚えていない顔もある。それでも、数だけの報告には戻さない」。竜はその声を遮らず、最後まで聞いた。'};return ['noel','lyra','garen'].filter(id=>S.allies?.includes(id)&&S.quests?.includes(id)).map(id=>`<p>${esc(voices[id])}</p>`).join('');}
function dragonJournal31(){if(!ensureCampaign().hiddenDiscovered)return '<section class="panel"><h2>まだ開いていない記録</h2><p>観測室の道を見つけると、ここに新しい記録が残ります。</p></section>';return `<section class="panel dragon-journal31"><h2>忘却の竜の記録</h2>${dragonArt31()}${dragonRecords31.map(r=>dragonStageOpen31(r.id)?`<details><summary>${r.title}</summary>${r.lines.map(line=>`<p>${esc(line)}</p>`).join('')}${r.id==='clear'?dragonCompanion31():''}</details>`:`<p class="small muted">${r.id==='before'?'挑戦前 · 仲間の約束を二つ果たすと解放':'討伐後 · 忘却の竜の討伐後に解放'}</p>`).join('')}</section>`;}


// Optional regional aftermaths: use existing read flags; no rewards or new save fields.
const interludes32=[{"title": "鐘のない朝", "art": "road", "lines": ["城門の外で、子どもたちが背比べをしていた。新しい線を刻む場所を尋ねられ、門番は少し考えてから、倒れた鐘の台座を指した。誰も鐘を鳴らそうとはしなかった。", "森へ渡る荷車には毛布と水が積まれていた。城に残る者が、出ていく者の荷紐を結んでいる。門が開いたことと、誰もがすぐ歩けることは違っていた。", "あなたは妹の手紙の折り目を確かめた。王が止めた音を、答えの代わりには出来ない。森の向こうで何があったのか、本人の言葉へ辿り着きたかった。"]}, {"title": "返事を待つ椅子", "art": "road", "lines": ["魔女の家の窓辺に、椅子が二脚並んだ。一脚には下書きが山積みになっていたが、魔女は紙を床へ移した。「次に来た人が、座れるように」。そう言って窓を開けた。", "道へ戻ると、根に引っかかった赤い糸の先が見えた。妹が歩いた道を示すものだと思っていた糸は、引き返す人が迷わないよう、枝にも結ばれていた。", "あなたは新しい糸を足さなかった。すでにある結び目をほどけないよう締め直す。妹を追うことが、妹のしたことを知る旅にもなっていた。"]}, {"title": "次の頁を開く", "art": "road", "lines": ["宿営地の机には、まだ使われていない茶碗が一つ置かれていた。誰の席かを決める札はない。今ここにいない者が戻った時、座れる場所だけが空けてあった。", "星図を広げると、港までの道が折り目で途切れた。あなたは両端へ石を置いて伸ばす。城の避難路も、森の小道も、その線の途中にある。別々の救出だと思っていたことが、同じ仕組みの縁で重なっていた。", "妹へ届ける返事の下に、あなたは問いを一つ書き足した。「帰れる道を、ほかの人にも残せるだろうか」。答えを先に書かず、星の見える方角へ荷物を向けた。"]}, {"title": "数え直す星", "art": "road", "lines": ["観測台の記録板には、閉じた門の数だけが並んでいた。管理人は一行を消しかけ、手を止めた。代わりに余白へ、今日開いた道を一本描く。古い失敗を消さずに、新しい記録を足した。", "階段の下では、港へ下りる者たちが出発を待っていた。見張り役が海図を渡すと、一人が帰りの便の時刻を書き込む。観測する側も、見られるだけだった側も、同じ紙を使い始めていた。", "あなたは、窓に映らなかった明日のことを考えた。船が出るかどうかは、まだ分からない。だから港へ行く。見えた未来をなぞるためではなく、そこで待つ人の話を聞くために。"]}, {"title": "ほどいた綱の行方", "art": "letters", "lines": ["出航した船が見えなくなると、船具屋の女は空いた杭へ腰を下ろした。長く握っていた綱の跡が、掌に残っている。「次は、帰ってきた船を結ぶ番ね」。綱を捨てず、足元へ巻き直した。", "灯台から短い合図が来た。提督が次の見張りを呼んでいる。港の者は顔を見合わせ、それから一人が階段を上がった。火を守る仕事が、少しずつ一人の役目でなくなっていく。", "船上で、あなたは日誌の生存者の頁に薄紙を挟んだ。山へ届いた積荷の行方を確かめるためだ。失った名を忘れずに、今も歩いている名を追う。船は北へ進んだ。"]}, {"title": "雪解けを待たずに", "art": "letters", "lines": ["山の麓で、配達鞄を直す職人に出会った。凍った留め金を温めると、革に残った小さな穴が見える。「ここから水が入ったんだな」。職人は新しい糸を通した。勇気の話だけでは、次の手紙を濡らさずに済まない。", "巡礼者の道しるべには、天候と休める小屋の場所が書き足された。帰れなかった者を讃える碑のそばに、生きて越えるための覚え書きが並ぶ。誰かが、火の燃料も補充していった。", "あなたは妹の書かなかった続きを、そのまま鞄へ戻した。書庫で探すのは、妹の気持ちを決めつける証拠ではない。本人が答えを選べるようにする、もう一つの設計だった。"]}, {"title": "貸し出された原典", "art": "letters", "lines": ["司書は原典を机の端まで運び、貸出票を探した。戻す日を書く欄で、指が止まる。あなたは、その欄を空けたまま受け取った。使い終える前から、期限を決めたくはなかった。", "廊下では、棚の位置を書き写す者と、宛先を尋ねる者が並んでいた。すぐ届けられない手紙もある。司書は読める名だけを紙へ移し、分からない箇所には空白を残した。", "原典は軽かった。皆で支える道を選ぶなら、ここに書かれていない人の手が要る。楔を砕くなら、変わった世界で歩き直す覚悟が要る。あなたは二つとも妹へ伝えるため、最後の門へ向かった。"]}, {"title": "まだ決めていない明日", "art": "letters", "lines": ["門のそばで、妹が長く黙っていた。あなたも返事を急がせず、荷物を下ろした。王に伝えた言葉を、ここで守れなくしてはいけないと思った。", "原典の余白を見ていると、妹の声がした。「帰ったら、まず眠りたい」。あなたはうなずいた。世界の行方を選ぶ前にも、選んだあとにも、一人の人が疲れて休む時間は必要だった。", "あなたは二つの道をもう一度確かめた。どちらを選んでも、その後に困ることまで消えるわけではない。それでも今は、困った時に話せる相手がいる。結末を選ぶ言葉を、一緒に探し始めた。"]}];
function interludeArt32(key){const road=key==='road';return `<figure class="story-figure story-wide24"><img src="assets/interlude-${road?'road':'letters'}32.webp" alt="${road?'人々の帰路を照らす、城門に残された灯':'窓辺に届いた手紙と、空けられた席'}" loading="lazy" decoding="async"><figcaption>${road?'灯をつなぐ道':'届いた手紙'}</figcaption></figure>`;}
function interludeJournal32(){const seen=ensureNovel22().seen;return `<section class="panel interlude-journal32"><h2>旅の幕間 · 残された場所の明日</h2><p class="small muted">各章の攻略後の場面を読むと、その土地の続きを読めます。</p>${interludes32.map((r,a)=>seen.includes(`${a}:clear`)?`<details><summary>第${a+1}章のあと · ${r.title}</summary>${interludeArt32(r.art)}${r.lines.map(line=>`<p>${esc(line)}</p>`).join('')}</details>`:`<p class="small muted">第${a+1}章の幕間 · 未解放</p>`).join('')}</section>`;}


// Companion camp conversations, gated by existing membership, promises and read scenes.
const companionCamp33={"noel": {"afterTitle": "鳴らさない夜", "after": ["ノエルは鐘を布で包んでいた。音を消したいのかと尋ねると、首を振る。「寝てる人がいるから」。城門の前で握り締めていた手は、今は布の端を丁寧に折っていた。", "あなた「兄さんは、どんな人だった？」。少年は少し考えた。「パンの固いところを、自分の皿に取る人」。勇敢だったかどうかとは違う話を、初めて聞いた。", "「名前だけ残したら、あとは忘れてもいいのかと思ってた」。ノエルは膝の上の包みを見る。「でも、こういう話をしてもいいんだね」。あなたは、もう少し聞かせてほしいと答えた。", "鐘を置いても、少年はすぐ立たなかった。あなたが火へ薪を足すと、兄が一度だけパンを焦がした日の話を始めた。話し終えた時、二人とも少し笑っていた。"], "beforeTitle": "呼び戻す音、送り出す音", "before": ["ノエルは荷物の紐に、小さな鐘を結び直した。「最後の門でも、鳴らすかもしれない」。何を知らせるつもりか尋ねると、少年はしばらく答えなかった。", "「兄さんが戻る音には、ならないんだよね」。あなたは、ならない、と答えた。火のはぜる音が間に入る。言い換えなかったことを、ノエルは責めなかった。", "「じゃあ、今ここにいる人へ鳴らす。怖くなったら、こっちに仲間がいるって分かるように」。あなたはうなずいた。誰かを忘れるために、次の役目を決めたわけではなかった。", "出発の前に、少年は鐘へ指を添えた。まだ音は出さない。「妹さんにも、帰ってから兄さんの話をしていい？」。あなたは、本人に聞いてみようと答えた。"], "endings": {"dawn": "ノエルは、変わった道に鐘の音がどこまで届くか確かめた。遠くから旅人が手を振る。「聞こえるんだ」。兄の名を入れた板を鞄へ戻し、今ここにいる相手へ手を振り返した。", "watch": "見回りの引き継ぎに、ノエルは短い鐘の合図を提案した。「出発は一度、戻ったら二度」。誰かが聞き損ねた時は呼びに行く、と当番表の横へ付け足した。"}}, "lyra": {"afterTitle": "一杯を自分のために", "after": ["包みを送り出したあとも、リラは火の前で薬草を分けていた。一袋作るたび、残りを数える。あなたは湯を二杯に分け、片方を彼女の手元へ置いた。", "「私の分は、あとで」。そう言ってから、リラは手を止めた。湯気が細くなるまで見つめ、両手で杯を持つ。「こう言うの、癖になってたんだね」", "あなた「休むと、誰かを見捨てた気がする？」。彼女はすぐにはうなずかなかった。「間に合わなかった時、休んだ時間のせいに出来てしまうから」。薬草の葉が、一枚だけ指に残っていた。", "返事が届く保証はない。それでも、返事を待つ人まで倒れてよいわけではなかった。リラは今夜使う分だけを袋へ戻した。「続きは朝にする」。あなたも薪を足す手を止めた。"], "beforeTitle": "手当ての、その先", "before": ["リラは最後の包みを閉じ、あなたの荷物へ結んだ。「妹さんの分だけ、特別に多くはしていないよ」。あなたは、分かっていると答えた。それを約束して、一緒に歩き始めたのだ。", "「帰ってきたら、元の生活に戻れるって思ってた」。彼女は自分の薬袋を持ち直す。「でも、戻った人にも変わってしまったことがある。薬では治せないことも」", "あなた「会ってから、困っていることを聞こう」。リラは小さく息を吐いた。「うん。先に元気な顔を求めないようにしよう」。妹の返事を急がせない理由が、もう一つ言葉になった。", "火を消す前に、彼女は自分の杯を洗った。「帰ったら、何も煎じないお茶を飲みたい」。その小さな予定を、あなたは荷物の重さと同じくらい確かなものとして覚えた。"], "endings": {"dawn": "リラは初めて見る浅瀬の草を、すぐには摘まなかった。故郷へ帰る道を確かめ、持ち帰った葉を誰と調べるか考える。「全部、一人で覚えなくていいね」。空いた薬袋を畳んだ。", "watch": "当番を終えたリラは、薬を作る火とは別に湯を沸かした。何も煎じないお茶だった。次の当番が出ていくまで、休む者の席に座って、その一杯を飲み終えた。"}}, "garen": {"afterTitle": "盾の裏の結び目", "after": ["ガレンは盾の裏の革紐を外していた。名を読み終えた日の傷で、留め金が歪んでいる。「これでは、次に支える時に抜ける」。あなたは新しい紐の端を持った。", "以前の紐は、簡単には外せない結び方になっていた。「持ち場を離れるな、と教わった」。ガレンは古い結び目を切った。逃げたくなかった自分にも、都合のよい命令だったと続ける。", "あなた「妹に会ったら、何を話す？」。ガレンは盾を伏せた。「私がしたことを。命じられたことと、自分で選んだことを、分けて」。許されるかを尋ねる言葉は、その中になかった。", "新しい紐には、手を離せば外せる留め具をつけた。あなたが確かめると、ガレンは自分でも引いた。「次の人へ渡せるように」。盾は同じ重さのまま、二人の間に置かれた。"], "beforeTitle": "答えを預けない", "before": ["ガレンは最後の門の方角を見ていた。「話を聞いてもらう前に、戦いが終わってしまうかもしれない」。あなたは、今ここで伝えたいことがあるのかと尋ねた。", "「私が倒れたら、少女へ謝罪を伝えてくれ」。口にしたあと、彼は目を伏せた。「いや。それでは、最後まで誰かへ預けてしまう」。盾の革紐を、自分の腕へ締め直す。", "あなた「生きて、話すための位置にいてくれ」。ガレンは顔を上げた。「私だけが残るためではなく、戻って話すために」。門を支える仕事と、門に残り続けることを、同じ誓いにはしなかった。", "出発の合図が来ても、彼は先に立たなかった。皆が荷物を確かめるまで待ち、最後に火の始末をする。命令がなくても出来る小さな仕事を、一つ選んだ。"], "endings": {"dawn": "ガレンは妹との話を、あなたへ報告しなかった。あとで頼まれたのは、荷車の車輪を直す手伝いだった。許しの有無を成果にせず、明日必要な仕事へ手を伸ばした。", "watch": "ガレンは当番表の自分の名を、一人分の枠に書いた。空いた欄をすべて埋めようとして、やめる。次の者に盾の留め方を教え、交代の時刻になったら門を離れた。"}}};

function campStageOpen33(id,stage){if(!S.allies?.includes(id)||!S.quests?.includes(id))return false;if(stage==='after')return true;if(stage==='before')return ensureNovel22().seen.includes('6:clear');if(stage==='ending')return !!ensureCampaign().epilogue20;return false;}
function campPortrait33(id){return `<figure class="story-figure story-wide24"><img src="assets/camp-${id}33.webp" alt="焚き火のそばの${esc(companions.find(c=>c.id===id).name)}" loading="lazy" decoding="async"><figcaption>${esc(companions.find(c=>c.id===id).name)} · 夜の宿営地</figcaption></figure>`;}
function campJournal33(){const available=companions.filter(c=>campStageOpen33(c.id,'after'));return `<section class="panel companion-camp33"><h2>焚き火を囲む夜</h2><p class="small muted">仲間との約束を果たすと会話が増えます。終盤と結末の会話は、物語の進行に合わせて解放されます。</p>${available.map(c=>{const r=companionCamp33[c.id];return `<details><summary>${esc(c.name)} · 約束のその後</summary>${campPortrait33(c.id)}<h3>${r.afterTitle}</h3>${r.after.map(line=>`<p>${esc(line)}</p>`).join('')}${campStageOpen33(c.id,'before')?`<details><summary>${r.beforeTitle}</summary>${r.before.map(line=>`<p>${esc(line)}</p>`).join('')}</details>`:'<p class="small muted">最後の旅支度 · 第7章の攻略後の場面を読むと解放</p>'}${campStageOpen33(c.id,'ending')?`<details><summary>帰路で果たした小さな約束</summary><p>${esc(r.endings[ensureCampaign().epilogue20])}</p></details>`:'<p class="small muted">帰路の会話 · 遠征編の結末を選ぶと解放</p>'}</details>`;}).join('')||'<p>約束を果たした仲間が宿営地に戻ると、その後の言葉をここで読めます。</p>'}</section>`;}
function campAccess33(){return companions.some(c=>campStageOpen33(c.id,'after'))?'<section class="panel"><h2>焚き火を囲む夜</h2><p>旅の手を休め、仲間との約束の続きを聞く。</p><button class="btn secondary" onclick="showModal(\'camp33\')">焚き火で仲間と話す</button></section>':'';}


// Sister viewpoint: reader-only short stories, no collectible or save field.
const sisterStories34=[{"id": "letter", "gate": "1:clear", "title": "封をするまで", "art": "letter", "lines": ["手紙の最初には「大丈夫」と書いた。少女はその二文字を見つめ、紙を裏返す。大丈夫なら、知らせなくてもよかった。そう思い直して、もう一枚を机へ引き寄せた。", "「迎えに来て」と書くまでに、灯の油が少し減った。相手を危険な場所へ呼ぶ言葉だった。それでも、何も言わずにいなくなる方がよいとは、もう思えなかった。", "封をしたあと、少女は端を一度開きかけた。言い訳を足したくなったのだ。やめて、折り目だけを押さえる。怖いという言葉はまだ書けなかったが、見つけてほしいという願いは残せた。"]}, {"id": "route", "gate": "4:discovery", "title": "帰る人のための糸", "art": "letter", "lines": ["原典の行方を尋ねて森を歩いた日、少女は赤い糸を枝へ結んだ。往路のためだけではない。話を聞いて引き返すことになっても、同じ道へ戻れるようにしておきたかった。", "魔女の家へ着くと、先に湯を勧められた。「急いでいるんです」。そう言った声が震え、少女はようやく冷えた手に気づく。杯を受け取ってから、封印が崩れるという噂を尋ねた。", "道を教わっても、答えを持ち帰れたわけではなかった。少女は帰りに、ほどけかけた糸を結び直した。次に来る時は、一人で来なくてもよい。そのことだけでも、知らせようと思った。"]}, {"id": "unsent", "gate": "5:discovery", "title": "消したままの一行", "art": "letter", "lines": ["北へ向かう使者を待つあいだ、少女は手紙の末尾に「もし間に合わなかったら」と書いた。続けようとして、何度も同じ場所で筆が止まった。誰かに託す別れの言葉を、まだ選びたくなかった。", "紙を破らず、その一行だけ消した。弱く見られるのが嫌だったからではない。帰れないことを、決まった未来のように書きたくなかった。怖さは、消した跡の下に残った。", "使者へ渡す時、少女は何も付け足さなかった。「届いたら、返事を待っていると伝えてください」。手紙の重さより、その短い頼みを口にする方が難しかった。"]}, {"id": "knock", "gate": "6:clear", "title": "二度の音を待つ", "art": "door", "lines": ["扉の向こうへ声が届かない夜、少女は木の節を二度叩いた。子どもの頃、暗い部屋で互いの居場所を確かめた合図だった。すぐには返事がなく、手を下ろしかけた。", "遠くで二度、音がした。何を選んでくれるのかは、まだ分からない。それでも、そこにいることだけは分かった。少女は扉から離れ、ようやく息を吐いた。", "次に話せたら、助けてくれたことより先に、怖かったと伝えようと思った。勇気がなかったことにはならない。怖いまま閉じた扉を、自分の言葉で開け直したかった。"]}, {"id": "answer", "gate": "7:clear", "title": "返事の余白", "art": "door", "lines": ["届いた返事を、少女はすぐには読み終えなかった。迎えに行くという言葉の先に、自分の話を聞くと書かれていた。何を言えばよいか、まだ整っていなかった。", "「帰りたい」と言ったあとで、戻るのが怖いと言ってもよいのだろうか。以前と同じ自分を待たれていたら、どうしよう。少女はその問いを、隠さず持ち帰ることにした。", "返事の余白へ、まだ答えを書かない。次に交わす言葉は、手紙の形でなくてもよかった。扉の向こうへ二度、音を返す。今度は、話を始める合図だった。"]}];

function sisterJournal34(){const seen=ensureNovel22().seen;return `<section class="panel sister-journal34"><h2>妹の側にあった時間</h2><p class="small muted">あなたが知った真相に合わせて読める、妹の視点の短編。旅の途中の回想です。</p>${sisterStories34.map(r=>seen.includes(r.gate)?`<details><summary>${r.title}</summary><figure class="story-figure story-wide24"><img src="assets/sister-${r.art}34.webp" alt="${r.art==='letter'?'手紙に言葉を残す妹':'扉に二度の合図を返す妹'}" loading="lazy" decoding="async"><figcaption>妹の視点 · ${r.title}</figcaption></figure>${r.lines.map(line=>`<p>${esc(line)}</p>`).join('')}</details>`:`<p class="small muted">第${Number(r.gate[0])+1}章・${novelStages22[r.gate.split(':')[1]]}の場面を読むと短編が解放</p>`).join('')}</section>`;}

const storyArt23=['妹の手紙と灰の城門','魔女と封印の設計図','玉座と封印の向こうの妹','星骸の天文台','灯を取り戻した港','雪山に眠る届かなかった手紙','沈黙の書庫と原典','夜明けへ続く帰り道'];
function storyIllustration23(a,stage,page=0){
 let src=null,caption='';
 if(a===2&&stage==='arrival'){src='assets/story-lastlight-arrival38.webp';caption='最後の灯火へ辿り着く。妹が守った避難者たちの街';}
 else if(a===2&&stage==='discovery'){src='assets/story-lastlight-discovery38.webp';caption='封印の門の向こうに、帰りたいと願う妹の声が響く';}
 else if(a===2&&stage==='before'){src='assets/story-lastlight-before38.webp';caption='深淵の君主が迫る選択。誰を鍵に残すのか';}
 else if(a===2&&stage==='clear'){src='assets/story-lastlight-clear38.webp';caption='闇の退いた玉座の背で、次の旅路を示す星図が灯る';}
 else if(a===3&&stage==='discovery'){src='assets/story-observatory-record37.webp';caption='星図の裏に記された、最初の鍵と封印の記録';}
 else if(a===7&&(stage==='discovery'||stage==='before')){src='assets/story-king27.webp';caption='最後の王と、空いたままの椅子';}
 else if(a===4&&(stage==='arrival'||stage==='discovery'||stage==='before')){src='assets/story-harbor26.webp';caption='灯を閉ざした港と灰潮の提督';}
 else if(a===6&&(stage==='before'||stage==='clear')){src='assets/story-library26.webp';caption='司書が隠していた、もう一つの頁';}
 else if(a===1&&(stage==='discovery'||stage==='before')){src='assets/story-witch25.webp';caption='魔女が隠していた、未完成の封印';}
 else if(a===5&&(stage==='before'||stage==='clear')){src='assets/story-snow25.webp';caption='巡礼者から託される、届かなかった手紙';}
 else if(a===0&&stage==='clear'){src='assets/story-bell24.webp';caption='三度目の鐘を止める骸骨王';}
 else if((a===0&&stage==='discovery'&&page>=2)||(a===1&&stage==='clear')){src='assets/story-sister24.webp';caption='回想 · 最後の避難者を守る妹';}
 if(src)return `<figure class="story-figure story-wide24"><img src="${classArt29(src)}" alt="${caption}" decoding="async"><figcaption>${caption}</figcaption><details class="story-enlarge24"><summary>絵を大きく見る</summary><img src="${classArt29(src)}" alt="${caption} · 拡大" loading="lazy"></details></figure>`;
 const art=a===7&&stage!=='clear'?2:a;caption=a===7&&stage!=='clear'?'黎明を阻む王と最後の門':storyArt23[a];return `<figure class="story-figure"><div class="story-illustration story-illustration-${art}" style="background-image:url('${classArt29('assets/story-atlas23.webp')}')" role="img" aria-label="${caption}"></div><figcaption>${caption}</figcaption></figure>`;
}
function epilogueArt24(id){return id==='watch'?`<figure class="story-figure story-wide24"><img src="${classArt29('assets/story-watch24.webp')}" alt="開かれた門に、妹と帰路の灯を置く" loading="lazy"><figcaption>境界を見守る灯</figcaption></figure>`:storyIllustration23(7,'clear');}

const novelStages22={arrival:'到着',discovery:'真相',before:'決戦前',clear:'攻略後'};
function validNovel22(n){const keys=Object.keys(novelStages22);const keyOK=k=>typeof k==='string'&&/^([0-7]):(arrival|discovery|before|clear)$/.test(k);return n&&n.version===1&&Array.isArray(n.seen)&&n.seen.length<=32&&new Set(n.seen).size===n.seen.length&&n.seen.every(keyOK)&&(n.active==null||keyOK(n.active))&&Number.isInteger(n.page)&&n.page>=0&&n.page<4;}
function ensureNovel22(){const cp=ensureCampaign();if(!cp.novel22){cp.novel22={version:1,seen:[],active:null,page:0};for(const a of cp.cleared)for(const stage of Object.keys(novelStages22))cp.novel22.seen.push(`${a}:${stage}`);}return cp.novel22;}
function queueNovel22(act,stage){const n=ensureNovel22(),key=`${act}:${stage}`;if(!novel22[act]||!novelStages22[stage]||n.seen.includes(key)||n.active)return;n.active=key;n.page=0;}
function prepareNovel22(){if(!S)return;const n=ensureNovel22();if(!n.active&&S.screen==='map'){const a=S.act;if(!n.seen.includes(`${a}:arrival`))queueNovel22(a,'arrival');else if(S.row>=(S.route45?7:2)&&!n.seen.includes(`${a}:discovery`))queueNovel22(a,'discovery');else if(S.row===S.map.length-1)queueNovel22(a,'before');}if(n.active&&['map','hub'].includes(S.screen)){modal={type:'novel22'};save();}}
function legacyNovelScene56(){const n=ensureNovel22();if(!n.active)return '';const [a,stage]=n.active.split(':'),scene=novel22[Number(a)];return `<div class="modal-cover novel-cover"><section class="panel modal novel-scene" role="dialog" aria-modal="true" aria-label="メインストーリー"><p class="eyebrow">MAIN STORY · 第${Number(a)+1}地域 · ${novelStages22[stage]}</p><h2>${chapters[a].title}</h2><p class="novel-question">${scene.question}</p>${storyIllustration23(Number(a),stage,n.page)}<p class="novel-line" role="status">${esc(storyLine24(Number(a),stage,n.page))}</p><p class="small muted">${n.page+1} / ${scene[stage].length} · 深淵の記録</p><div class="actions"><button class="btn secondary" onclick="novelPage22(-1)" ${n.page===0?'disabled':''}>前へ</button><button class="btn" onclick="novelPage22(1)">${n.page===scene[stage].length-1?'冒険へ戻る':'続きを読む'}</button><button class="btn secondary" onclick="finishNovel22()">この場面をスキップ</button></div><p class="small muted">読んだ場面は「物語」から読み返せます。${stage==='clear'?'「旅の幕間」に、この土地の続きを追加しました。':''}${Number(a)===7&&stage==='clear'?'続いて拠点で「遠征編の結末」を選べます。':''}</p></section></div>`;}
function legacyNovelPage56(step){if(modal?.type!=='novel22'||![-1,1].includes(step))return;const n=ensureNovel22();if(!n.active)return;const [a,stage]=n.active.split(':'),last=novel22[Number(a)][stage].length-1;if(n.page===last&&step===1)return finishNovel22();n.page=Math.max(0,Math.min(last,n.page+step));save();render();}
function finishNovel22(){const n=ensureNovel22();if(!n.active)return;if(!n.seen.includes(n.active))n.seen.push(n.active);n.active=null;n.page=0;modal=null;save();render();}
function novelJournal22(){const n=ensureNovel22();return `<div class="story-reader35"><p class="small muted">本編の既読場面 ${n.seen.length}/32。第3章の結末のあとも、第4〜8章へ旅は続きます。短編・幕間・仲間の会話は、以下から任意に読めます。</p><section class="panel"><h2>妹を追う旅 · 全8章</h2><p>手紙を手がかりに、封印の理由と帰り道を探す物語。</p>${novel22.map((r,a)=>`<details><summary>第${a+1}章 ${chapters[a].title} · ${n.seen.filter(k=>k.startsWith(a+':')).length}/4場面</summary><p class="gold">${n.seen.some(k=>k.startsWith(a+':'))?r.question:'この地域へ進むと物語が開きます。'}</p>${Object.entries(novelStages22).map(([stage,label])=>n.seen.includes(`${a}:${stage}`)?`<details><summary>${label}</summary>${journalScene25(a,stage)}</details>`:`<p class="small muted">${label} · 未読</p>`).join('')}</details>`).join('')}<p class="small muted">以前の版で攻略済みの地域は読み返し用に解放。初攻略の途中・再挑戦では既読の場面を繰り返し表示しません。</p></section>${sisterJournal34()}${campJournal33()}${interludeJournal32()}${letterJournal26()}${companionJournal28()}${dragonJournal31()}</div>`;}

