function routeGraph(){if(!S.route45)return legacy45_routeGraph();const h=1510,gap=100,top=55,y=r=>h-top-r*gap;let lines='';S.route45.links.forEach((es,r)=>es.forEach(([a,b])=>{const done=S.routeChoices[r]===a&&S.routeChoices[r+1]===b,next=r===S.row-1&&S.routeChoices[r]===a||S.row===0&&r===0;lines+=`<path d="M ${S.route45.positions[r][a]*3.6} ${y(r)} C ${S.route45.positions[r][a]*3.6} ${y(r)-45},${S.route45.positions[r+1][b]*3.6} ${y(r+1)+45},${S.route45.positions[r+1][b]*3.6} ${y(r+1)}" class="${done?'trail-done':next?'trail-next':''}"/>`;}));return `<div class="route-legend"><span>下から上へ · 点線でつながる道だけ進めます</span><button class="btn small secondary" onclick="focusRoute45()">現在地へ</button></div><div class="parchment-scroll45"><div class="route-map parchment45" style="height:${h}px"><svg viewBox="0 0 360 ${h}" preserveAspectRatio="none" aria-hidden="true">${lines}</svg>${S.map.map((row,r)=>`<div class="route-map-row" style="top:${y(r)}px"><span class="route-step-label">${r+1}</span>${row.map((type,i)=>{const taken=S.routeChoices[r]===i,available=routeAvailable(r,i);return `<button class="route-map-node ${type} ${available?'available':''} ${taken?'taken':''} ${r===S.row?'current-row':''} ${r<S.row&&!taken?'missed':''}" style="left:${S.route45.positions[r][i]}%" onclick="inspectRoute(${r},${i})" aria-label="${r+1}段目 ${routeNodeLabel45(r,i)} ${taken?'通過済み':available?'進める':'詳細を見る'}"><span>${taken&&r<S.row?'✓':nodeInfo[type][0]}</span><b>${routeNodeLabel45(r,i)}</b></button>`;}).join('')}</div>`).join('')}</div></div><div class="route-legend"><span>⚔ 通常戦</span><span>💀 精鋭</span><span>❔ 事件</span><span>⚖ 商店</span><span>🔥 休息</span><span>🎁 宝箱</span><span>♧ 旅路</span><span>👑 ボス</span></div>`;}
