function legacyMap56(){if(!S.route45)return legacy45_mapScreen();const ch=chapters[S.act],pace=routeEnemyScale45(S.row===14);return `${replayNotice21()}<section class="route-heading"><div class="eyebrow">REGION ${S.act+1} · ${S.row+1}/15段目 · ${difficulties[S.difficulty||'standard'].name}</div><h1>${ch.title}</h1><p>${ch.goal}</p>${S.preparation46?`<p class="gold">準備中：${trailPeople46[S.preparation46.kind].name}の支援 · 次の1戦で消費</p>`:''}<details><summary>物語と今回の目的</summary><p>${ch.intro}</p></details></section>${S.lastEvent?`<div class="event-receipt"><strong>${esc(S.lastEvent.title)}</strong><span>${esc(S.lastEvent.text)}</span></div>`:''}<div class="section-label"><h2>進む道を選ぶ</h2><button class="btn secondary" onclick="showModal('retreat')">拠点へ撤退</button></div><p class="route-balance-note">全15段・各段最大5マス。配置と道は出発ごとに変化。敵は深さと道中勝利数に応じて強化されます。道中 ${S.route45.budget.battles}勝 · 現在の章内補正 HP×${pace.hp.toFixed(2)}／攻撃×${pace.attack.toFixed(2)}。商店の削除・強化などは取扱店のみ。</p>${routeGraph()}<section class="panel route-current"><h2>現在地 ${S.row+1}/15 · 今、進める場所</h2><div class="route-choices">${S.map[S.row].map((type,i)=>routeAvailable(S.row,i)?`<button class="route-choice ${type}" onclick="enterNode(${i})"><span class="route-icon">${nodeInfo[type][0]}</span><span><b>${routeNodeLabel45(S.row,i)}</b><small>${type==='shop'?shopDescriptions50[S.route45.shops[S.row][i]]:type==='trail'?'旅人と取引して次の1戦に備える':routeDetails[type]}</small></span><span class="route-arrow">→</span></button>`:'').join('')}</div></section>`;}

