function validShop50(sh){if(!validShopPrices53(sh))return false;return sh.version50===1&&Object.hasOwn(shopDescriptions50,sh.kind45)&&Array.isArray(sh.offers50)&&sh.offers50.length<=3&&sh.offers50.every(o=>o&&Number.isInteger(o.price)&&o.price>0&&((o.type==='relic50'&&relics.some(r=>r[0]===o.id))||(o.type==='medicine50'&&Object.hasOwn(medicines50,o.id))||o.type==='trade50'))&&Array.isArray(sh.upgraded50)&&sh.upgraded50.every(id=>sh.items?.includes(id))&&sh.tradeOptions50&&typeof sh.tradeOptions50==='object'&&!Array.isArray(sh.tradeOptions50)&&Object.entries(sh.tradeOptions50).every(([id,ids])=>C[id]&&Array.isArray(ids)&&ids.length<=3&&new Set(ids).size===ids.length&&ids.every(x=>C[x]&&x!==id&&C[x].rarity===C[id].rarity&&C[x].type!=='curse'))&&(sh.special50==null||typeof sh.special50==='string');}
function shopBuy(type,idx){if(S?.screen!=='shop'||!S.shop||!shopPaymentAllowed53(type,idx))return;if(!S?.shop?.version50)return oldShopBuy50(type,idx);if(S.screen!=='shop')return;const sh=S.shop;if(type==='card'){const id=sh.items[idx];if(!Number.isInteger(idx)||!id||sh.purchased.includes('c'+idx)||!canSpend53(sh.cardPrices45[idx]))return;S.gold-=sh.cardPrices45[idx];S.deck.push(sh.upgraded50.includes(id)?upgradedId54(id):baseCard54(id));sh.purchased.push('c'+idx);save();render();return;}return oldShopBuy50(type,idx);}
