function offerTile50(o,i){const sh=S.shop,key='o'+i,used=sh.purchased.includes(key),m=medicines50[o.id],r=relics.find(r=>r[0]===o.id),blocked=used||!canSpend53(o.price)||(o.type==='relic50'&&S.relics.includes(o.id))||(o.type==='medicine50'&&(m.prep?!!S.preparation46:S.hp>=S.maxHp));const limit55=o.type==='relic50'&&sh.kind45==='relic'&&relicBought55(sh);const title=o.type==='relic50'?r[2]+' '+r[1]:o.type==='trade50'?'⚒ カード交換':m.name,desc=o.type==='relic50'?r[3]:o.type==='trade50'?'選んだ1枚を同レアリティの候補3枚から交換。枚数を増やさず改善。':m.desc;return `<section class="panel shop-tile"><b>${esc(title)}</b>${sh.special50===key?'<span class="gold">特価20%引き</span>':''}<p>${esc(desc)}</p>${o.type==='medicine50'&&m.prep?'<p class="small muted">次戦用の準備は旅路の支援と合わせて1枠。戦闘開始時に消費。</p>':''}<button class="btn" onclick="buyOffer50(${i})" ${blocked||limit55?'disabled':''}>${used?'売り切れ':limit55?'この店の遺物は購入済み':S.relics.includes(o.id)&&o.type==='relic50'?'所持済み':o.price+'G '+(o.type==='trade50'?'交換を選ぶ':'購入')}</button></section>`;}
function shopScreen(){if(!S.shop?.version50)return oldShopScreen50();const sh=S.shop;return `<section class="chapter"><div class="eyebrow">TRAVELLING MARKET</div><h1>${shopKinds45[sh.kind45]}</h1><p>${shopDescriptions50[sh.kind45]}</p><p class="small muted">品ぞろえと交換候補は保存され、再読み込みでは変わりません。各商品・サービスは1回限り。</p><p class="gold">所持金 ${S.gold}G</p>${S.preparation46?`<p>準備中：${trailPeople46[S.preparation46.kind].name} · 次の1戦で消費（1枠）</p>`:''}</section><div class="shop-grid">${sh.items.map((id,i)=>{const c=cardDetail(id,sh.upgraded50.includes(id)),key='c'+i,used=sh.purchased.includes(key);return `<section class="panel shop-tile rarity-${c.rarity}"><div class="shop-card-title47"><b>${esc(c.name)}${c.up?'＋':''}</b>${shopCost47(c)}</div>${sh.special50===key?'<span class="gold">特価20%引き</span>':''}<p>${esc(cardText(c))}</p><small>${rarityNames[c.rarity]}${sh.upgraded50.includes(id)?' · 強化済み。この商品1枚だけに強化を適用。':''}</small><button class="btn" onclick="shopBuy('card',${i})" ${used||!canSpend53(sh.cardPrices45[i])?'disabled':''}>${used?'売り切れ':sh.cardPrices45[i]+'G 購入'}</button></section>`;}).join('')}${sh.services45.map(type=>{const used=sh.purchased.includes(type),price=sh.prices45[type];return `<section class="panel shop-tile"><b>${type==='upgrade'?'選んだカードを強化':'カードを1枚削除'}</b>${sh.special50===type?'<span class="gold">特価20%引き</span>':''}<p>${type==='upgrade'?'未強化カード1枚だけを強化。選択確定時に支払い。':'最低5枚を残し、選んだ1枚を削除。'}</p><button class="btn" onclick="shopBuy('${type}')" ${used||!canSpend53(price)||(type==='upgrade'?!upgradeableCards39().length:S.deck.length<=5)?'disabled':''}>${used?'利用済み':price+'G 選択する'}</button></section>`;}).join('')}${sh.offers50.map(offerTile50).join('')}</div><button class="btn" onclick="resolveNode()">店を出て進む →</button>`;}

