function installPager56(host,content,key){const previous=pages56.get(key)?.index||0,units=units56(content),nav=document.createElement('nav');nav.className='page56-nav';nav.setAttribute('aria-label','ページ切り替え');nav.innerHTML='<button class="btn secondary" data-prev>前へ</button><span></span><button class="btn secondary" data-next>次へ</button>';host.parentElement.append(nav);nav.querySelector('[data-prev]').onclick=()=>pageTurn56(key,-1);nav.querySelector('[data-next]').onclick=()=>pageTurn56(key,1);const model={index:previous,pages:[],nav};function newPage(){const p=document.createElement('div');p.className='page56-page';host.append(p);model.pages.push(p);return p;}let page=newPage();const room=()=>host.clientHeight-2;function add(unit){page.append(unit);if(page.scrollHeight<=room())return;if(page.children.length>1){unit.remove();page=newPage();page.append(unit);}if(page.scrollHeight<=room())return;if(['P','SMALL','H1','H2','H3','H4'].includes(unit.tagName)||!unit.children.length&&unit.tagName!=='INPUT'){const text=unit.textContent;unit.remove();const chunks=splitText56(text,t=>{unit.textContent=t;page.append(unit);const fit=page.scrollHeight<=room();unit.remove();return fit;});chunks.forEach((t,i)=>{const part=unit.cloneNode(false);part.textContent=t;page.append(part);if(i<chunks.length-1)page=newPage();});}else if(!unit.matches('button,label,input,select')&&unit.children.length){unit.remove();for(const child of [...unit.children])add(child);}else{unit.classList.add('compact56');}}
units.forEach(add);
// Compact an overflowed page before accepting a mostly empty final page.
for(let i=0;i<model.pages.length-1;i++){const current=model.pages[i],next=model.pages[i+1];if(!next.children.length)continue;current.classList.add('dense58');while(next.firstElementChild){const unit=next.firstElementChild;current.append(unit);if(current.scrollHeight>room()){next.prepend(unit);break;}}if(!next.children.length){next.remove();model.pages.splice(i+1,1);i--;}}
// Avoid a lone final control: move its preceding context to the last page when it fits.
if(model.pages.length>1){const last=model.pages.at(-1),prev=model.pages.at(-2);if(last.children.length===1&&last.firstElementChild.matches('button,.actions')){const context=prev.lastElementChild;if(context&&prev.children.length>1){last.prepend(context);if(last.scrollHeight>room())prev.append(context);}}}
model.index=Math.min(previous,model.pages.length-1);pages56.set(key,model);showPage56(model);}
