// Ver.0.61: Standard only. Chapters 1-2 and chapter 3 road encounters are unchanged.
const standardBoss57=[null,null,{hp:.88,attack:.82,special:.75,dot:1},{hp:.90,attack:.85,special:.82,dot:.85},{hp:.90,attack:.85,special:.82,dot:.85},{hp:.90,attack:.85,special:.82,dot:.85},{hp:.88,attack:.84,special:.80,dot:.85},{hp:.88,attack:.84,special:.80,dot:.85}];
const standardRoad57=[null,null,null,{hp:.94,attack:.94,special:.94,dot:1},{hp:.94,attack:.94,special:.94,dot:1},{hp:.92,attack:.93,special:.93,dot:1},{hp:.90,attack:.92,special:.92,dot:1},{hp:.90,attack:.92,special:.92,dot:1}];
const stagger57=[18,23,23,27,31,35,39,43];
function tuningFor57(t,type,hidden=false){if(!t||(t.difficulty||'standard')!=='standard'||hidden)return null;if(type==='part')return t.act>=2?{hp:.90,attack:1,special:1,dot:1}:null;if(type==='escort')return t.act>=2?{hp:.88,attack:t.act===2?.82:.85,special:t.act===2?.82:.85,dot:1}:null;return type==='boss'?standardBoss57[t.act]:standardRoad57[t.act];}
function tuneEnemy57(e,t,type,hidden=false){if(e.tuning57)return false;const f=tuningFor57(t,type,hidden);if(!f)return false;const oldMax=e.maxHp,oldAtk=e.atk;e.maxHp=Math.max(1,Math.round(oldMax*f.hp));e.hp=e.hp<=0?0:Math.min(e.maxHp,Math.max(1,Math.round(e.hp/oldMax*e.maxHp)));e.atk=oldAtk===0?0:Math.max(1,Math.round(oldAtk*f.attack));if(e.intent?.kind==='attack'){e.intent.value=Math.max(0,e.atk+Math.round(Math.max(0,e.intent.value-oldAtk)*f.special));}else if(e.intent?.kind==='poison')e.intent.value=Math.max(1,Math.round(e.intent.value*f.dot));e.tuning57={...f};return true;}
function migrateBalance57(t){const b=t?.battle;if(!b||!Array.isArray(b.enemies))return t;const hidden=!!(b.hidden||b.tuningHidden57);for(let i=0;i<b.enemies.length;i++){const e=b.enemies[i],kind=e.bossPart?'part':b.bossMechanic&&i>0?'escort':b.type;tuneEnemy57(e,t,kind,hidden);tuneElite60(e,t,kind,hidden);weakenChapter4Elite(e,t,kind,hidden);weakenChapter7Enemy(e,t,kind,hidden);if(kind==='elite'&&!hidden)capEliteCaptainHeavy(e,t);}const tele=b.bossMechanic?.telegraph;if(tele&&(t.difficulty||'standard')==='standard'&&t.act>=2&&!hidden){tele.needed=stagger57[t.act];if(!tele.stopped&&tele.damage>=tele.needed&&b.enemies[0].intent.kind==='charge'){tele.stopped=true;b.enemies[0].intent={kind:'stagger',value:0};b.enemies[0].skipHeavy=true;}}return t;}

