// v0.59: read-only, exact direct-effect preview. No RNG, save or battle mutation.
function cardPreviewValues59(c,b=S.battle){
 const fx=c.effect,enemies=b.enemies.map(e=>({...e})),selected=b.enemies[b.selected]?.hp>0?b.selected:b.enemies.findIndex(e=>e.hp>0),target=enemies[selected],damage=enemies.map(()=>0),absorbed=enemies.map(()=>0);
 if(!target)return {damage,absorbed,block:0,heal:0,selfDamage:0};
 function hit(enemy,amount){if(enemy.hp<=0)return;const i=enemies.indexOf(enemy),raw=Math.max(0,Math.round(amount*(enemy.vuln>0?1.5:1))),shield=Math.min(enemy.block,raw),loss=Math.min(enemy.hp,raw-shield);enemy.block-=shield;enemy.hp-=loss;damage[i]+=loss;absorbed[i]+=shield;}
 const weak=b.weak>0?.75:1;
 if(fx.hit)for(let i=0;i<(fx.hits||1);i++)hit(target,Math.max(0,fx.hit+synergyBonus(fx,target,b)+b.str)*weak);
 if(fx.aoe)for(const e of enemies)if(e.hp>0)hit(e,Math.max(0,fx.aoe+synergyBonus(fx,e,b)+b.str)*weak);
 if(fx.blockHit)hit(target,Math.round(b.block*fx.blockHit*weak));
 if(fx.executeHit)hit(target,Math.round((fx.executeHit+b.str)*(target.hp<=target.maxHp/2?2:1)*weak));
 if(fx.detonate&&target.hp>0&&target.poison>0)hit(target,Math.round(target.poison*fx.detonate*weak));
 const guard=cardGuardEffects(c,b,S.hp);const selfDamage=fx.selfDamage?Math.min(Math.max(0,S.hp-1),fx.selfDamage):guard.hpCost;
 return {damage,absorbed,block:guard.block,selfDamage,heal:Math.min(cardHealing(fx,S.hp,S.maxHp),S.maxHp-S.hp+selfDamage)};
}
function cardPreview59(c){const v=cardPreviewValues59(c),b=S.battle,fx=c.effect,parts=[];
 if(fx.hit||fx.aoe||fx.blockHit||fx.executeHit||fx.detonate){for(let i=0;i<b.enemies.length;i++){if(b.enemies[i].hp<=0||!fx.aoe&&b.enemies[i]!==battleTarget51())continue;parts.push(`${b.enemies[i].name}：HP −${v.damage[i]}${v.absorbed[i]?`（防御で${v.absorbed[i]}軽減）`:''}`);}}
 if(v.block)parts.push(`防御 +${v.block}`);if(fx.heal)parts.push(`HP回復 +${v.heal}`);if(v.selfDamage)parts.push(`自分のHP −${v.selfDamage}`);
 // Other effects retain their existing wording; poison is separate from immediate HP loss.
 const other={...fx};for(const key of ['hit','hits','aoe','blockHit','executeHit','detonate','block','guardBlock','comboBlock','crowdBlock','threatBlock','paidBlock','hpPrice','intentHit','blockDamageCap','heal','selfDamage','poison','allPoison','poisonHit','bleedHit','weakHit','guardHit','comboHit'])delete other[key];
 if(fx.poison)parts.push(`毒 +${fx.poison+(fx.poisonBonus||0)+(b.poisonBonus||0)}`);
 if(fx.existingPoison){
   const names=b.enemies.filter(enemy=>enemy.hp>0&&enemy.poison>0).map(enemy=>enemy.name);
   parts.push(names.length?names.join('・')+'：毒 +'+(fx.existingPoison+(b.poisonBonus||0)):'追加の毒：対象なし');
   delete other.existingPoison;
 }
 if(fx.allPoison)parts.push(`敵全員の毒 +${fx.allPoison+(fx.poisonBonus||0)+(b.poisonBonus||0)}`);
 if(fx.bloodPact)other.selfDamage=fx.selfDamage;const rest=cardText({...c,effect:other,previewCostShown:true});if(rest)parts.push(rest);
 return parts.join(' / ')||cardText(c);
}
function enemyIntent59(e){const k=e.intent.kind,n=e.intent.value,icons={attack:'⚔',defend:'盾',protect:'盾',buff:'↑',charge:'⚠',poison:'毒',heal:'＋',stagger:'✓'};const text=k==='attack'?`${e.intent.label||'攻撃'} ${Math.max(0,Math.round(n*(e.weak>0?.75:1)))}${(e.intent.hits||1)>1?'×'+e.intent.hits:''}ダメージ`:intentText(e);return `<span class="intent59-icon">${icons[k]||'◆'}</span> ${esc(text)}`;}
